import Foundation

/// A complete, offline MITRE ATT&CK (Enterprise) knowledge base: all 15 current tactics
/// and all 227 top-level techniques (sub-techniques, e.g. T1556.006, are out of scope),
/// each with MITRE's own description plus general detection/mitigation guidance for its
/// tactic. Generated from the live attack.mitre.org Enterprise matrix. For planning and
/// understanding adversary behaviour on authorised engagements / CTFs — a reference to
/// actually learn from, not a cherry-picked sample.
public enum MitreAttack {
    public struct Technique: Identifiable, Sendable {
        public let id: String            // e.g. T1059
        public let name: String
        public let tactics: [String]     // tactic ids this technique belongs to, e.g. [TA0002]
        public let summary: String
        public let detection: String
        public let mitigation: String
        public init(_ id: String, _ name: String, _ tactics: [String], _ summary: String, detect: String, mitigate: String) {
            self.id = id; self.name = name; self.tactics = tactics; self.summary = summary
            self.detection = detect; self.mitigation = mitigate
        }
    }

    public struct Tactic: Identifiable, Sendable {
        public let id: String            // e.g. TA0001
        public let name: String
        public let summary: String
    }

    public static let tactics: [Tactic] = [
        Tactic(id: "TA0043", name: "Reconnaissance", summary: "Gathering information to plan future operations."),
        Tactic(id: "TA0042", name: "Resource Development", summary: "Establishing resources to support operations."),
        Tactic(id: "TA0001", name: "Initial Access", summary: "Getting into the network."),
        Tactic(id: "TA0002", name: "Execution", summary: "Running adversary-controlled code."),
        Tactic(id: "TA0003", name: "Persistence", summary: "Maintaining a foothold across restarts."),
        Tactic(id: "TA0004", name: "Privilege Escalation", summary: "Gaining higher-level permissions."),
        Tactic(id: "TA0005", name: "Stealth", summary: "Hiding and concealing actions to appear as normal behavior."),
        Tactic(id: "TA0112", name: "Defense Impairment", summary: "Breaking security mechanisms, pipelines and tooling so defenders can't see or trust what's happening."),
        Tactic(id: "TA0006", name: "Credential Access", summary: "Stealing account names and passwords."),
        Tactic(id: "TA0007", name: "Discovery", summary: "Learning about the environment."),
        Tactic(id: "TA0008", name: "Lateral Movement", summary: "Moving through the environment."),
        Tactic(id: "TA0009", name: "Collection", summary: "Gathering data of interest."),
        Tactic(id: "TA0011", name: "Command and Control", summary: "Communicating with compromised systems."),
        Tactic(id: "TA0010", name: "Exfiltration", summary: "Stealing data out of the network."),
        Tactic(id: "TA0040", name: "Impact", summary: "Manipulating, interrupting or destroying systems/data."),
    ]

    public static let techniques: [Technique] = [
        Technique("T1548", "Abuse Elevation Control Mechanism", ["TA0004"], "Adversaries may circumvent mechanisms designed to control privilege elevation to gain higher-level permissions. Most modern systems contain native elevation control mechanisms that are intended to limit privileges that a user can perform on a machine. Authorization has to be granted to specific users in order to perform tasks that can be considered of higher risk. An adversary can perform several methods to take advantage of built-in control mechanisms in order to escalate privileges on a system.", detect: "EDR telemetry around exploit attempts, sudo/UAC bypass patterns, and unexpected token/process manipulation are the main signals.", mitigate: "Patch known escalation vulnerabilities, enforce least privilege, and keep elevation mechanisms (UAC, sudoers) tightly configured."),
        Technique("T1134", "Access Token Manipulation", ["TA0004", "TA0005"], "Adversaries may modify access tokens to operate under a different user or system security context to perform actions and bypass access controls. Windows uses access tokens to determine the ownership of a running process. A user can manipulate access tokens to make a running process appear as though it is the child of a different process or belongs to someone other than the user that started the process. When this occurs, the process also takes on the security context associated with the new token.", detect: "EDR telemetry around exploit attempts, sudo/UAC bypass patterns, and unexpected token/process manipulation are the main signals.", mitigate: "Patch known escalation vulnerabilities, enforce least privilege, and keep elevation mechanisms (UAC, sudoers) tightly configured."),
        Technique("T1531", "Account Access Removal", ["TA0040"], "Adversaries may interrupt availability of system and network resources by inhibiting access to accounts utilized by legitimate users. Accounts may be deleted, locked, or manipulated (ex: changed credentials, revoked permissions for SaaS platforms such as Sharepoint) to remove access to accounts. Adversaries may also subsequently log off and/or perform a System Shutdown/Reboot to set malicious changes into place.", detect: "Mass file writes/deletes/renames, shadow-copy deletion, and unexpected shutdown/reboot events are late-stage, high-confidence signals.", mitigate: "Offline backups, least privilege and EDR are the last line of defence once an adversary reaches this stage."),
        Technique("T1087", "Account Discovery", ["TA0007"], "Adversaries may attempt to get a listing of valid accounts, usernames, or email addresses on a system or within a compromised environment. This information can help adversaries determine which accounts exist, which can aid in follow-on behavior such as brute-forcing, spear-phishing attacks, or account takeovers (e.g., Valid Accounts).", detect: "Bursts of enumeration commands (whoami, net user, ipconfig, AD queries) in a short window from one host are the giveaway.", mitigate: "Segmentation and limiting discovery-protocol exposure won't stop discovery outright but slows and narrows what's learned."),
        Technique("T1098", "Account Manipulation", ["TA0003", "TA0004"], "Adversaries may manipulate accounts to maintain and/or elevate access to victim systems. Account manipulation may consist of any action that preserves or modifies adversary access to a compromised account, such as modifying credentials or permission groups. These actions could also include account activity designed to subvert security policies, such as performing iterative password updates to bypass password duration policies and preserve the life of compromised credentials.", detect: "Monitor for new services, scheduled tasks, startup entries and account/key changes — persistence usually leaves a durable artifact.", mitigate: "Least privilege, restricting who can create services/tasks/accounts, and regular audits of autostart locations close most persistence paths."),
        Technique("T1650", "Acquire Access", ["TA0042"], "Adversaries may purchase or otherwise acquire an existing access to a target system or network. A variety of online services and initial access broker networks are available to sell access to previously compromised systems. In some cases, adversary groups may form partnerships to share compromised systems with each other.", detect: "Happens on adversary-controlled infrastructure, so it's invisible to your monitoring; rely on threat-intel feeds for newly-registered domains/certificates tied to known campaigns.", mitigate: "Block or flag indicators from threat-intel feeds (new domains, abused certificates) before they're used against you."),
        Technique("T1583", "Acquire Infrastructure", ["TA0042"], "Adversaries may buy, lease, rent, or obtain infrastructure that can be used during targeting. A wide variety of infrastructure exists for hosting and orchestrating adversary operations. Infrastructure solutions include physical or cloud servers, domains, and third-party web services. Some infrastructure providers offer free trial periods, enabling infrastructure acquisition at limited to no cost. Additionally, botnets are available for rent or purchase.", detect: "Happens on adversary-controlled infrastructure, so it's invisible to your monitoring; rely on threat-intel feeds for newly-registered domains/certificates tied to known campaigns.", mitigate: "Block or flag indicators from threat-intel feeds (new domains, abused certificates) before they're used against you."),
        Technique("T1595", "Active Scanning", ["TA0043"], "Adversaries may execute active reconnaissance scans to gather information that can be used during targeting. Active scans are those where the adversary probes victim infrastructure via network traffic, as opposed to other forms of reconnaissance that do not involve direct interaction.", detect: "Largely pre-compromise and hard to see from inside your network; watch for scanning noise against your assets and monitor your own exposure in Shodan/Censys/CT logs.", mitigate: "Minimise what's publicly discoverable (banners, WHOIS, exposed services) — this stage is about reducing attack surface, not stopping the adversary directly."),
        Technique("T1557", "Adversary-in-the-Middle", ["TA0006", "TA0009"], "Adversaries may attempt to position themselves between two or more networked devices using an adversary-in-the-middle (AiTM) technique to support follow-on behaviors such as Network Sniffing, Transmitted Data Manipulation, or replay attacks (Exploitation for Credential Access). By abusing features of common networking protocols that can determine the flow of network traffic (e.g. ARP, DNS, LLMNR, etc.), adversaries may force a device to communicate through an adversary controlled system so they can collect information or perform additional actions.", detect: "Failed-login spikes, LSASS/SAM/shadow access, and access to credential stores (browsers, password managers) are the classic signals.", mitigate: "MFA, credential-guard/LAPS-style protections, secret scanning and rotating any exposed credential are the highest-value controls."),
        Technique("T1700", "AI-Enabled Exfiltration", ["TA0010"], "Adversaries may utilize Direct Prompt Injection, Indirect Prompt Injection or other methods to instruct enterprise AI agents to exfiltrate data. When enterprise systems incorporate the use of AI assistants or other AI agents, adversaries may abuse these systems to weaponize sanctioned tools available to the agent.", detect: "Outbound volume anomalies and uploads to unsanctioned cloud/web services are the main signal.", mitigate: "DLP, egress limits and blocking/allowlisting web services reduce how data can leave undetected."),
        Technique("T1696", "Anti-Automation Evasion", ["TA0005"], "Adversaries may employ various means to evade or complete automation checks. Automation checks distinguish human users from bot traffic and prevent bots from reaching the web pages protected by automation checks. For example, a user may be required to solve a CAPTCHA challenge before accessing a form or login page. Traditional CAPTCHAs ask the user to decipher a string of characters, type the characters into a box, and submit the form. reCAPTCHA asks the user to identify images, click a checkbox, or evaluate the user’s behavior from mouse movement and device cookies.", detect: "Behavioural/EDR detection and centralised logging matter here, since the goal is to blend in or hide rather than be loud.", mitigate: "Forward logs off-host, use application control, and favour behavioural over signature-based detection so evading one layer doesn't mean invisibility."),
        Technique("T1071", "Application Layer Protocol", ["TA0011"], "Adversaries may communicate using OSI application layer protocols to avoid detection/network filtering by blending in with existing traffic. Commands to the remote system, and often the results of those commands, will be embedded within the protocol traffic between the client and server.", detect: "Beaconing analysis, DNS/TLS anomalies and egress monitoring catch C2 channels trying to blend into normal traffic.", mitigate: "Egress filtering, proxy inspection and blocking known C2 infrastructure are the main levers here."),
        Technique("T1010", "Application Window Discovery", ["TA0007"], "Adversaries may attempt to get a listing of open application windows. Window listings could convey information about how the system is used. For example, information about application windows could be used identify potential data to collect as well as identifying security tooling (Security Software Discovery) to evade.", detect: "Bursts of enumeration commands (whoami, net user, ipconfig, AD queries) in a short window from one host are the giveaway.", mitigate: "Segmentation and limiting discovery-protocol exposure won't stop discovery outright but slows and narrows what's learned."),
        Technique("T1560", "Archive Collected Data", ["TA0009"], "An adversary may compress and/or encrypt data that is collected prior to exfiltration. Compressing the data can help to obfuscate the collected data and minimize the amount of data sent over the network. Encryption can be used to hide information that is being exfiltrated from detection or make exfiltration less conspicuous upon inspection by a defender.", detect: "Mass file access, staging directories, and bulk reads across many hosts are typical before data is moved out.", mitigate: "DLP, least privilege and encryption at rest limit what's useful to an adversary even if collection succeeds."),
        Technique("T1123", "Audio Capture", ["TA0009"], "An adversary can leverage a computer's peripheral devices (e.g., microphones and webcams) or applications (e.g., voice and video call services) to capture audio recordings for the purpose of listening into sensitive conversations to gather information.", detect: "Mass file access, staging directories, and bulk reads across many hosts are typical before data is moved out.", mitigate: "DLP, least privilege and encryption at rest limit what's useful to an adversary even if collection succeeds."),
        Technique("T1119", "Automated Collection", ["TA0009"], "Once established within a system or network, an adversary may use automated techniques for collecting internal data. Methods for performing this technique could include use of a Command and Scripting Interpreter to search for and copy information fitting set criteria such as file type, location, or name at specific time intervals.", detect: "Mass file access, staging directories, and bulk reads across many hosts are typical before data is moved out.", mitigate: "DLP, least privilege and encryption at rest limit what's useful to an adversary even if collection succeeds."),
        Technique("T1020", "Automated Exfiltration", ["TA0010"], "Adversaries may exfiltrate data, such as sensitive documents, through the use of automated processing after being gathered during Collection.", detect: "Outbound volume anomalies and uploads to unsanctioned cloud/web services are the main signal.", mitigate: "DLP, egress limits and blocking/allowlisting web services reduce how data can leave undetected."),
        Technique("T1197", "BITS Jobs", ["TA0002", "TA0003", "TA0005"], "Adversaries may abuse BITS jobs to persistently execute code and perform various background tasks. Windows Background Intelligent Transfer Service (BITS) is a low-bandwidth, asynchronous file transfer mechanism exposed through Component Object Model (COM). BITS is commonly used by updaters, messengers, and other applications preferred to operate in the background (using available idle bandwidth) without interrupting other networked applications. File transfer tasks are implemented as BITS jobs, which contain a queue of one or more file operations.", detect: "Process and command-line logging (EDR, PowerShell/Bash logging) catches most execution techniques as they run.", mitigate: "Application allowlisting and constrained scripting environments reduce what an adversary can execute even after they get in."),
        Technique("T1547", "Boot or Logon Autostart Execution", ["TA0003", "TA0004"], "Adversaries may configure system settings to automatically execute a program during system boot or logon to maintain persistence or gain higher-level privileges on compromised systems. Operating systems may have mechanisms for automatically running a program on system boot or account logon. These mechanisms may include automatically executing programs that are placed in specially designated directories or are referenced by repositories that store configuration information, such as the Windows Registry. An adversary may achieve the same goal by modifying or extending features of the kernel.", detect: "Monitor for new services, scheduled tasks, startup entries and account/key changes — persistence usually leaves a durable artifact.", mitigate: "Least privilege, restricting who can create services/tasks/accounts, and regular audits of autostart locations close most persistence paths."),
        Technique("T1037", "Boot or Logon Initialization Scripts", ["TA0003", "TA0004"], "Adversaries may use scripts automatically executed at boot or logon initialization to establish persistence. Initialization scripts can be used to perform administrative functions, which may often execute other programs or send information to an internal logging server. These scripts can vary based on operating system and whether applied locally or remotely.", detect: "Monitor for new services, scheduled tasks, startup entries and account/key changes — persistence usually leaves a durable artifact.", mitigate: "Least privilege, restricting who can create services/tasks/accounts, and regular audits of autostart locations close most persistence paths."),
        Technique("T1217", "Browser Information Discovery", ["TA0007"], "Adversaries may enumerate information about browsers to learn more about compromised environments. Data saved by browsers (such as bookmarks, accounts, and browsing history) may reveal a variety of personal information about users (e.g., banking sites, relationships/interests, social media, etc.) as well as details about internal network resources such as servers, tools/dashboards, or other related infrastructure.", detect: "Bursts of enumeration commands (whoami, net user, ipconfig, AD queries) in a short window from one host are the giveaway.", mitigate: "Segmentation and limiting discovery-protocol exposure won't stop discovery outright but slows and narrows what's learned."),
        Technique("T1185", "Browser Session Hijacking", ["TA0009"], "Adversaries may take advantage of security vulnerabilities and inherent functionality in browser software to change content, modify user-behaviors, and intercept information as part of various browser session hijacking techniques.", detect: "Mass file access, staging directories, and bulk reads across many hosts are typical before data is moved out.", mitigate: "DLP, least privilege and encryption at rest limit what's useful to an adversary even if collection succeeds."),
        Technique("T1110", "Brute Force", ["TA0006"], "Adversaries may use brute force techniques to gain access to accounts when passwords are unknown or when password hashes are obtained. Without knowledge of the password for an account or set of accounts, an adversary may systematically guess the password using a repetitive or iterative mechanism. Brute forcing passwords can take place via interaction with a service that will check the validity of those credentials or offline against previously acquired credential data, such as password hashes.", detect: "Failed-login spikes, LSASS/SAM/shadow access, and access to credential stores (browsers, password managers) are the classic signals.", mitigate: "MFA, credential-guard/LAPS-style protections, secret scanning and rotating any exposed credential are the highest-value controls."),
        Technique("T1612", "Build Image on Host", ["TA0005"], "Adversaries may build a container image directly on a host to bypass defenses that monitor for the retrieval of malicious images from a public registry. A remote build request may be sent to the Docker API that includes a Dockerfile that pulls a vanilla base image, such as alpine, from a public or local registry and then builds a custom image upon it.", detect: "Behavioural/EDR detection and centralised logging matter here, since the goal is to blend in or hide rather than be loud.", mitigate: "Forward logs off-host, use application control, and favour behavioural over signature-based detection so evading one layer doesn't mean invisibility."),
        Technique("T1115", "Clipboard Data", ["TA0009"], "Adversaries may collect data stored in the clipboard from users copying information within or between applications.", detect: "Mass file access, staging directories, and bulk reads across many hosts are typical before data is moved out.", mitigate: "DLP, least privilege and encryption at rest limit what's useful to an adversary even if collection succeeds."),
        Technique("T1651", "Cloud Administration Command", ["TA0002"], "Adversaries may abuse cloud management services to execute commands within virtual machines. Resources such as AWS Systems Manager, Azure RunCommand, and Runbooks allow users to remotely run scripts in virtual machines by leveraging installed virtual machine agents.", detect: "Process and command-line logging (EDR, PowerShell/Bash logging) catches most execution techniques as they run.", mitigate: "Application allowlisting and constrained scripting environments reduce what an adversary can execute even after they get in."),
        Technique("T1671", "Cloud Application Integration", ["TA0003"], "Adversaries may achieve persistence by leveraging OAuth application integrations in a software-as-a-service environment. Adversaries may create a custom application, add a legitimate application into the environment, or even co-opt an existing integration to achieve malicious ends.", detect: "Monitor for new services, scheduled tasks, startup entries and account/key changes — persistence usually leaves a durable artifact.", mitigate: "Least privilege, restricting who can create services/tasks/accounts, and regular audits of autostart locations close most persistence paths."),
        Technique("T1580", "Cloud Infrastructure Discovery", ["TA0007"], "An adversary may attempt to discover infrastructure and resources that are available within an infrastructure-as-a-service (IaaS) environment. This includes compute service resources such as instances, virtual machines, and snapshots as well as resources of other services including the storage and database services.", detect: "Bursts of enumeration commands (whoami, net user, ipconfig, AD queries) in a short window from one host are the giveaway.", mitigate: "Segmentation and limiting discovery-protocol exposure won't stop discovery outright but slows and narrows what's learned."),
        Technique("T1538", "Cloud Service Dashboard", ["TA0007"], "An adversary may use a cloud service dashboard GUI with stolen credentials to gain useful information from an operational cloud environment, such as specific services, resources, and features. For example, the GCP Command Center can be used to view all assets, review findings of potential security risks, and run additional queries, such as finding public IP addresses and open ports.", detect: "Bursts of enumeration commands (whoami, net user, ipconfig, AD queries) in a short window from one host are the giveaway.", mitigate: "Segmentation and limiting discovery-protocol exposure won't stop discovery outright but slows and narrows what's learned."),
        Technique("T1526", "Cloud Service Discovery", ["TA0007"], "An adversary may attempt to enumerate the cloud services running on a system after gaining access. These methods can differ from platform-as-a-service (PaaS), to infrastructure-as-a-service (IaaS), or software-as-a-service (SaaS). Many services exist throughout the various cloud providers and can include Continuous Integration and Continuous Delivery (CI/CD), Lambda Functions, Entra ID, etc. They may also include security services, such as AWS GuardDuty and Microsoft Defender for Cloud, and logging services, such as AWS CloudTrail and Google Cloud Audit Logs.", detect: "Bursts of enumeration commands (whoami, net user, ipconfig, AD queries) in a short window from one host are the giveaway.", mitigate: "Segmentation and limiting discovery-protocol exposure won't stop discovery outright but slows and narrows what's learned."),
        Technique("T1619", "Cloud Storage Object Discovery", ["TA0007"], "Adversaries may enumerate objects in cloud storage infrastructure. Adversaries may use this information during automated discovery to shape follow-on behaviors, including requesting all or specific objects from cloud storage. Similar to File and Directory Discovery on a local host, after identifying available storage services (i.e. Cloud Infrastructure Discovery) adversaries may access the contents/objects stored in cloud infrastructure.", detect: "Bursts of enumeration commands (whoami, net user, ipconfig, AD queries) in a short window from one host are the giveaway.", mitigate: "Segmentation and limiting discovery-protocol exposure won't stop discovery outright but slows and narrows what's learned."),
        Technique("T1059", "Command and Scripting Interpreter", ["TA0002"], "Adversaries may abuse command and script interpreters to execute commands, scripts, or binaries. These interfaces and languages provide ways of interacting with computer systems and are a common feature across many different platforms. Most systems come with some built-in command-line interface and scripting capabilities, for example, macOS and Linux distributions include some flavor of Unix Shell while Windows installations include the Windows Command Shell and PowerShell.", detect: "Process and command-line logging (EDR, PowerShell/Bash logging) catches most execution techniques as they run.", mitigate: "Application allowlisting and constrained scripting environments reduce what an adversary can execute even after they get in."),
        Technique("T1092", "Communication Through Removable Media", ["TA0011"], "Adversaries can perform command and control between compromised hosts on potentially disconnected networks using removable media to transfer commands from system to system. Both systems would need to be compromised, with the likelihood that an Internet-connected system was compromised first and the second through lateral movement by Replication Through Removable Media. Commands and files would be relayed from the disconnected system to the Internet-connected system to which the adversary has direct access.", detect: "Beaconing analysis, DNS/TLS anomalies and egress monitoring catch C2 channels trying to blend into normal traffic.", mitigate: "Egress filtering, proxy inspection and blocking known C2 infrastructure are the main levers here."),
        Technique("T1586", "Compromise Accounts", ["TA0042"], "Adversaries may compromise accounts with services that can be used during targeting. For operations incorporating social engineering, the utilization of an online persona may be important. Rather than creating and cultivating accounts (i.e. Establish Accounts), adversaries may compromise existing accounts. Utilizing an existing persona may engender a level of trust in a potential victim if they have a relationship, or knowledge of, the compromised persona.", detect: "Happens on adversary-controlled infrastructure, so it's invisible to your monitoring; rely on threat-intel feeds for newly-registered domains/certificates tied to known campaigns.", mitigate: "Block or flag indicators from threat-intel feeds (new domains, abused certificates) before they're used against you."),
        Technique("T1554", "Compromise Host Software Binary", ["TA0003"], "Adversaries may modify host software binaries to establish persistent access to systems. Software binaries/executables provide a wide range of system commands or services, programs, and libraries. Common software binaries are SSH clients, FTP clients, email clients, web browsers, and many other user or server applications.", detect: "Monitor for new services, scheduled tasks, startup entries and account/key changes — persistence usually leaves a durable artifact.", mitigate: "Least privilege, restricting who can create services/tasks/accounts, and regular audits of autostart locations close most persistence paths."),
        Technique("T1584", "Compromise Infrastructure", ["TA0042"], "Adversaries may compromise third-party infrastructure that can be used during targeting. Infrastructure solutions include physical or cloud servers, domains, network devices, and third-party web and DNS services. Instead of buying, leasing, or renting infrastructure an adversary may compromise infrastructure and use it during other phases of the adversary lifecycle. Additionally, adversaries may compromise numerous machines to form a botnet they can leverage.", detect: "Happens on adversary-controlled infrastructure, so it's invisible to your monitoring; rely on threat-intel feeds for newly-registered domains/certificates tied to known campaigns.", mitigate: "Block or flag indicators from threat-intel feeds (new domains, abused certificates) before they're used against you."),
        Technique("T1609", "Container Administration Command", ["TA0002"], "Adversaries may abuse a container administration service to execute commands within a container. A container administration service such as the Docker daemon, the Kubernetes API server, or the kubelet may allow remote management of containers within an environment.", detect: "Process and command-line logging (EDR, PowerShell/Bash logging) catches most execution techniques as they run.", mitigate: "Application allowlisting and constrained scripting environments reduce what an adversary can execute even after they get in."),
        Technique("T1613", "Container and Resource Discovery", ["TA0007"], "Adversaries may attempt to discover containers and other resources that are available within a containers environment. Other resources may include images, deployments, pods, nodes, and other information such as the status of a cluster.", detect: "Bursts of enumeration commands (whoami, net user, ipconfig, AD queries) in a short window from one host are the giveaway.", mitigate: "Segmentation and limiting discovery-protocol exposure won't stop discovery outright but slows and narrows what's learned."),
        Technique("T1659", "Content Injection", ["TA0001", "TA0011"], "Adversaries may gain access and continuously communicate with victims by injecting malicious content into systems through online network traffic. Rather than luring victims to malicious payloads hosted on a compromised website (i.e., Drive-by Target followed by Drive-by Compromise), adversaries may initially access victims through compromised data-transfer channels where they can manipulate traffic and/or inject their own content. These compromised online network channels may also be used to deliver additional payloads (i.e., Ingress Tool Transfer) and other data to already compromised systems.", detect: "Watch authentication logs, email gateways and perimeter IDS/WAF for the first foothold — new source IPs, unusual logins, sandboxed attachment detonations.", mitigate: "MFA, patching internet-facing services, email filtering and least-privilege access are the highest-value controls at this stage."),
        Technique("T1136", "Create Account", ["TA0003"], "Adversaries may create an account to maintain access to victim systems. With a sufficient level of access, creating such accounts may be used to establish secondary credentialed access that do not require persistent remote access tools to be deployed on the system.", detect: "Monitor for new services, scheduled tasks, startup entries and account/key changes — persistence usually leaves a durable artifact.", mitigate: "Least privilege, restricting who can create services/tasks/accounts, and regular audits of autostart locations close most persistence paths."),
        Technique("T1543", "Create or Modify System Process", ["TA0003", "TA0004"], "Adversaries may create or modify system-level processes to repeatedly execute malicious payloads as part of persistence. When operating systems boot up, they can start processes that perform background system functions. On Windows and Linux, these system processes are referred to as services. On macOS, launchd processes known as Launch Daemon and Launch Agent are run to finish system initialization and load user specific parameters.", detect: "Monitor for new services, scheduled tasks, startup entries and account/key changes — persistence usually leaves a durable artifact.", mitigate: "Least privilege, restricting who can create services/tasks/accounts, and regular audits of autostart locations close most persistence paths."),
        Technique("T1555", "Credentials from Password Stores", ["TA0006"], "Adversaries may search for common password storage locations to obtain user credentials. Passwords are stored in several places on a system, depending on the operating system or application holding the credentials. There are also specific applications and services that store passwords to make them easier for users to manage and maintain, such as password managers and cloud secrets vaults. Once credentials are obtained, they can be used to perform lateral movement and access restricted information.", detect: "Failed-login spikes, LSASS/SAM/shadow access, and access to credential stores (browsers, password managers) are the classic signals.", mitigate: "MFA, credential-guard/LAPS-style protections, secret scanning and rotating any exposed credential are the highest-value controls."),
        Technique("T1485", "Data Destruction", ["TA0040"], "Adversaries may destroy data and files on specific systems or in large numbers on a network to interrupt availability to systems, services, and network resources. Data destruction is likely to render stored data irrecoverable by forensic techniques through overwriting files or data on local and remote drives. Common operating system file deletion commands such as del and rm often only remove pointers to files without wiping the contents of the files themselves, making the files recoverable by proper forensic methodology. This behavior is distinct from Disk Content Wipe and Disk Structure Wipe because individual files are destroyed rather than sections of a storage disk or the disk's logical structure.", detect: "Mass file writes/deletes/renames, shadow-copy deletion, and unexpected shutdown/reboot events are late-stage, high-confidence signals.", mitigate: "Offline backups, least privilege and EDR are the last line of defence once an adversary reaches this stage."),
        Technique("T1132", "Data Encoding", ["TA0011"], "Adversaries may encode data to make the content of command and control traffic more difficult to detect. Command and control (C2) information can be encoded using a standard data encoding system. Use of data encoding may adhere to existing protocol specifications and includes use of ASCII, Unicode, Base64, MIME, or other binary-to-text and character encoding systems. Some data encoding systems may also result in data compression, such as gzip.", detect: "Beaconing analysis, DNS/TLS anomalies and egress monitoring catch C2 channels trying to blend into normal traffic.", mitigate: "Egress filtering, proxy inspection and blocking known C2 infrastructure are the main levers here."),
        Technique("T1486", "Data Encrypted for Impact", ["TA0040"], "Adversaries may encrypt data on target systems or on large numbers of systems in a network to interrupt availability to system and network resources. They can attempt to render stored data inaccessible by encrypting files or data on local and remote drives and withholding access to a decryption key. This may be done in order to extract monetary compensation from a victim in exchange for decryption or a decryption key (ransomware) or to render data permanently inaccessible in cases where the key is not saved or transmitted.", detect: "Mass file writes/deletes/renames, shadow-copy deletion, and unexpected shutdown/reboot events are late-stage, high-confidence signals.", mitigate: "Offline backups, least privilege and EDR are the last line of defence once an adversary reaches this stage."),
        Technique("T1530", "Data from Cloud Storage", ["TA0009"], "Adversaries may access data from cloud storage.", detect: "Mass file access, staging directories, and bulk reads across many hosts are typical before data is moved out.", mitigate: "DLP, least privilege and encryption at rest limit what's useful to an adversary even if collection succeeds."),
        Technique("T1602", "Data from Configuration Repository", ["TA0009"], "Adversaries may collect data related to managed devices from configuration repositories. Configuration repositories are used by management systems in order to configure, manage, and control data on remote systems. Configuration repositories may also facilitate remote access and administration of devices.", detect: "Mass file access, staging directories, and bulk reads across many hosts are typical before data is moved out.", mitigate: "DLP, least privilege and encryption at rest limit what's useful to an adversary even if collection succeeds."),
        Technique("T1213", "Data from Information Repositories", ["TA0009"], "Adversaries may leverage information repositories to mine valuable information. Information repositories are tools that allow for storage of information, typically to facilitate collaboration or information sharing between users, and can store a wide variety of data that may aid adversaries in further objectives, such as Credential Access, Lateral Movement, or Defense Evasion, or direct access to the target information. Adversaries may also abuse external sharing features to share sensitive documents with recipients outside of the organization (i.e., Transfer Data to Cloud Account).", detect: "Mass file access, staging directories, and bulk reads across many hosts are typical before data is moved out.", mitigate: "DLP, least privilege and encryption at rest limit what's useful to an adversary even if collection succeeds."),
        Technique("T1005", "Data from Local System", ["TA0009"], "Adversaries may search local system sources, such as file systems, configuration files, local databases, virtual machine files, or process memory, to find files of interest and sensitive data prior to Exfiltration.", detect: "Mass file access, staging directories, and bulk reads across many hosts are typical before data is moved out.", mitigate: "DLP, least privilege and encryption at rest limit what's useful to an adversary even if collection succeeds."),
        Technique("T1039", "Data from Network Shared Drive", ["TA0009"], "Adversaries may search network shares on computers they have compromised to find files of interest. Sensitive data can be collected from remote systems via shared network drives (host shared directory, network file server, etc.) that are accessible from the current system prior to Exfiltration. Interactive command shells may be in use, and common functionality within cmd may be used to gather information.", detect: "Mass file access, staging directories, and bulk reads across many hosts are typical before data is moved out.", mitigate: "DLP, least privilege and encryption at rest limit what's useful to an adversary even if collection succeeds."),
        Technique("T1025", "Data from Removable Media", ["TA0009"], "Adversaries may search connected removable media on computers they have compromised to find files of interest. Sensitive data can be collected from any removable media (optical disk drive, USB memory, etc.) connected to the compromised system prior to Exfiltration. Interactive command shells may be in use, and common functionality within cmd may be used to gather information.", detect: "Mass file access, staging directories, and bulk reads across many hosts are typical before data is moved out.", mitigate: "DLP, least privilege and encryption at rest limit what's useful to an adversary even if collection succeeds."),
        Technique("T1565", "Data Manipulation", ["TA0040"], "Adversaries may insert, delete, or manipulate data in order to influence external outcomes or hide activity, thus threatening the integrity of the data. By manipulating data, adversaries may attempt to affect a business process, organizational understanding, or decision making.", detect: "Mass file writes/deletes/renames, shadow-copy deletion, and unexpected shutdown/reboot events are late-stage, high-confidence signals.", mitigate: "Offline backups, least privilege and EDR are the last line of defence once an adversary reaches this stage."),
        Technique("T1001", "Data Obfuscation", ["TA0011"], "Adversaries may obfuscate command and control traffic to make it more difficult to detect. Command and control (C2) communications are hidden (but not necessarily encrypted) in an attempt to make the content more difficult to discover or decipher and to make the communication less conspicuous and hide commands from being seen. This encompasses many methods, such as adding junk data to protocol traffic, using steganography, or impersonating legitimate protocols.", detect: "Beaconing analysis, DNS/TLS anomalies and egress monitoring catch C2 channels trying to blend into normal traffic.", mitigate: "Egress filtering, proxy inspection and blocking known C2 infrastructure are the main levers here."),
        Technique("T1074", "Data Staged", ["TA0009"], "Adversaries may stage collected data in a central location or directory prior to Exfiltration. Data may be kept in separate files or combined into one file through techniques such as Archive Collected Data. Interactive command shells may be used, and common functionality within cmd and bash may be used to copy data into a staging location.", detect: "Mass file access, staging directories, and bulk reads across many hosts are typical before data is moved out.", mitigate: "DLP, least privilege and encryption at rest limit what's useful to an adversary even if collection succeeds."),
        Technique("T1030", "Data Transfer Size Limits", ["TA0010"], "An adversary may exfiltrate data in fixed size chunks instead of whole files or limit packet sizes below certain thresholds. This approach may be used to avoid triggering network data transfer threshold alerts.", detect: "Outbound volume anomalies and uploads to unsanctioned cloud/web services are the main signal.", mitigate: "DLP, egress limits and blocking/allowlisting web services reduce how data can leave undetected."),
        Technique("T1622", "Debugger Evasion", ["TA0005", "TA0007"], "Adversaries may employ various means to detect and avoid debuggers. Debuggers are typically used by defenders to trace and/or analyze the execution of potential malware payloads.", detect: "Behavioural/EDR detection and centralised logging matter here, since the goal is to blend in or hide rather than be loud.", mitigate: "Forward logs off-host, use application control, and favour behavioural over signature-based detection so evading one layer doesn't mean invisibility."),
        Technique("T1491", "Defacement", ["TA0040"], "Adversaries may modify visual content available internally or externally to an enterprise network, thus affecting the integrity of the original content. Reasons for Defacement include delivering messaging, intimidation, or claiming (possibly false) credit for an intrusion. Disturbing or offensive images may be used as a part of Defacement in order to cause user discomfort, or to pressure compliance with accompanying messages.", detect: "Mass file writes/deletes/renames, shadow-copy deletion, and unexpected shutdown/reboot events are late-stage, high-confidence signals.", mitigate: "Offline backups, least privilege and EDR are the last line of defence once an adversary reaches this stage."),
        Technique("T1678", "Delay Execution", ["TA0005"], "Adversaries may employ various time-based methods to evade detection and analysis. These techniques often exploit system clocks, delays, or timing mechanisms to obscure malicious activity, blend in with benign activity, and avoid scrutiny. Adversaries can perform this behavior within virtualization/sandbox environments or natively on host systems.", detect: "Behavioural/EDR detection and centralised logging matter here, since the goal is to blend in or hide rather than be loud.", mitigate: "Forward logs off-host, use application control, and favour behavioural over signature-based detection so evading one layer doesn't mean invisibility."),
        Technique("T1140", "Deobfuscate/Decode Files or Information", ["TA0005"], "Adversaries may use Obfuscated Files or Information to hide artifacts of an intrusion from analysis. They may require separate mechanisms to decode or deobfuscate that information depending on how they intend to use it. Methods for doing that include built-in functionality of malware or by using utilities present on the system.", detect: "Behavioural/EDR detection and centralised logging matter here, since the goal is to blend in or hide rather than be loud.", mitigate: "Forward logs off-host, use application control, and favour behavioural over signature-based detection so evading one layer doesn't mean invisibility."),
        Technique("T1610", "Deploy Container", ["TA0002"], "Adversaries may deploy a container into an environment to facilitate execution or evade defenses. In some cases, adversaries may deploy a new container to execute processes associated with a particular image or deployment, such as processes that execute or download malware. In others, an adversary may deploy a new container configured without network rules, user limitations, etc. to bypass existing defenses within the environment. In Kubernetes environments, an adversary may attempt to deploy a privileged or vulnerable container into a specific node in order to Escape to Host and access other containers running on the node.", detect: "Process and command-line logging (EDR, PowerShell/Bash logging) catches most execution techniques as they run.", mitigate: "Application allowlisting and constrained scripting environments reduce what an adversary can execute even after they get in."),
        Technique("T1587", "Develop Capabilities", ["TA0042"], "Adversaries may build capabilities that can be used during targeting. Rather than purchasing, freely downloading, or stealing capabilities, adversaries may develop their own capabilities in-house. This is the process of identifying development requirements and building solutions such as malware, exploits, and self-signed certificates. Adversaries may develop capabilities to support their operations throughout numerous phases of the adversary lifecycle.", detect: "Happens on adversary-controlled infrastructure, so it's invisible to your monitoring; rely on threat-intel feeds for newly-registered domains/certificates tied to known campaigns.", mitigate: "Block or flag indicators from threat-intel feeds (new domains, abused certificates) before they're used against you."),
        Technique("T1652", "Device Driver Discovery", ["TA0007"], "Adversaries may attempt to enumerate local device drivers on a victim host. Information about device drivers may highlight various insights that shape follow-on behaviors, such as the function/purpose of the host, present security tools (i.e. Security Software Discovery) or other defenses (e.g., Virtualization/Sandbox Evasion), as well as potential exploitable vulnerabilities (e.g., Exploitation for Privilege Escalation).", detect: "Bursts of enumeration commands (whoami, net user, ipconfig, AD queries) in a short window from one host are the giveaway.", mitigate: "Segmentation and limiting discovery-protocol exposure won't stop discovery outright but slows and narrows what's learned."),
        Technique("T1699", "Direct Prompt Injection", ["TA0002"], "Adversaries may input malicious prompts directly into an LLM’s user interface. The prompts can be designed to bypass safeguards, manipulate context, override previous instructions, or coerce the LLM into unauthorized behavior.", detect: "Process and command-line logging (EDR, PowerShell/Bash logging) catches most execution techniques as they run.", mitigate: "Application allowlisting and constrained scripting environments reduce what an adversary can execute even after they get in."),
        Technique("T1006", "Direct Volume Access", ["TA0005"], "Adversaries may directly access a volume to bypass file access controls and file system monitoring. Windows allows programs to have direct access to logical volumes. Programs with direct access may read and write files directly from the drive by analyzing file system data structures. This technique may bypass Windows file access controls as well as file system monitoring tools.", detect: "Behavioural/EDR detection and centralised logging matter here, since the goal is to blend in or hide rather than be loud.", mitigate: "Forward logs off-host, use application control, and favour behavioural over signature-based detection so evading one layer doesn't mean invisibility."),
        Technique("T1686", "Disable or Modify System Firewall", ["TA0112"], "Adversaries may disable or modify host-based or network firewalls to impair defensive mechanisms and enable further action. Once an adversary has gathered sufficient privileges, they can tamper with firewall services, policies, or rule sets to remove restrictions on inbound or outbound traffic. For example, this may include turning off firewall profiles, altering existing rules to permit previously blocked ports or protocols, or adding new rules that create covert communication paths (e.g., adding a new firewall rule for a well-known protocol (such as RDP) using a non-traditional and potentially less securitized port.", detect: "Alert on any attempt to disable, reconfigure or tamper with security tooling itself (AV/EDR stopped, logging turned off, firewall rules changed) — these are high-confidence signals on their own.", mitigate: "Tamper-protect security agents, centralise logs off-host, and treat any successful tampering attempt as an incident regardless of what else is seen."),
        Technique("T1685", "Disable or Modify Tools", ["TA0112"], "Adversaries may disable, degrade, or tamper with security tools or applications (e.g., endpoint detection and response (EDR) tools, intrusion detection systems (IDS), antivirus, logging agents, sensors, etc.) to impair or reduce visibility of defensive capabilities. This may include stopping specific services, killing processes, modifying or deleting tool configuration files and Registry keys, or preventing tools from updating. This may also include impairing defenses more broadly by disrupting preventative, detection, and response mechanisms across host, network, and cloud environments.", detect: "Alert on any attempt to disable, reconfigure or tamper with security tooling itself (AV/EDR stopped, logging turned off, firewall rules changed) — these are high-confidence signals on their own.", mitigate: "Tamper-protect security agents, centralise logs off-host, and treat any successful tampering attempt as an incident regardless of what else is seen."),
        Technique("T1561", "Disk Wipe", ["TA0040"], "Adversaries may wipe or corrupt raw disk data on specific systems or in large numbers in a network to interrupt availability to system and network resources. With direct write access to a disk, adversaries may attempt to overwrite portions of disk data. Adversaries may opt to wipe arbitrary portions of disk data and/or wipe disk structures like the master boot record (MBR). A complete wipe of all disk sectors may be attempted.", detect: "Mass file writes/deletes/renames, shadow-copy deletion, and unexpected shutdown/reboot events are late-stage, high-confidence signals.", mitigate: "Offline backups, least privilege and EDR are the last line of defence once an adversary reaches this stage."),
        Technique("T1484", "Domain or Tenant Policy Modification", ["TA0004", "TA0112"], "Adversaries may modify the configuration settings of a domain or identity tenant to evade defenses and/or escalate privileges in centrally managed environments. Such services provide a centralized means of managing identity resources such as devices and accounts, and often include configuration settings that may apply between domains or tenants such as trust relationships, identity syncing, or identity federation.", detect: "EDR telemetry around exploit attempts, sudo/UAC bypass patterns, and unexpected token/process manipulation are the main signals.", mitigate: "Patch known escalation vulnerabilities, enforce least privilege, and keep elevation mechanisms (UAC, sudoers) tightly configured."),
        Technique("T1482", "Domain Trust Discovery", ["TA0007"], "Adversaries may attempt to gather information on domain trust relationships that may be used to identify lateral movement opportunities in Windows multi-domain/forest environments. Domain trusts provide a mechanism for a domain to allow access to resources based on the authentication procedures of another domain. Domain trusts allow the users of the trusted domain to access resources in the trusting domain. The information discovered may help the adversary conduct SID-History Injection, Pass the Ticket, and Kerberoasting. Domain trusts can be enumerated using the DSEnumerateDomainTrusts() Win32 API call, .NET methods, and LDAP. The Windows utility Nltest is known to be used by adversaries to enumerate domain trusts.", detect: "Bursts of enumeration commands (whoami, net user, ipconfig, AD queries) in a short window from one host are the giveaway.", mitigate: "Segmentation and limiting discovery-protocol exposure won't stop discovery outright but slows and narrows what's learned."),
        Technique("T1689", "Downgrade Attack", ["TA0112"], "Adversaries may downgrade or use a version of system features that may be outdated, vulnerable, and/or does not support updated security controls. Downgrade attacks typically take advantage of a system’s backward compatibility to force it into less secure modes of operation.", detect: "Alert on any attempt to disable, reconfigure or tamper with security tooling itself (AV/EDR stopped, logging turned off, firewall rules changed) — these are high-confidence signals on their own.", mitigate: "Tamper-protect security agents, centralise logs off-host, and treat any successful tampering attempt as an incident regardless of what else is seen."),
        Technique("T1189", "Drive-by Compromise", ["TA0001"], "Adversaries may gain access to a system through a user visiting a website over the normal course of browsing. Multiple ways of delivering exploit code to a browser exist (i.e., Drive-by Target), including:", detect: "Watch authentication logs, email gateways and perimeter IDS/WAF for the first foothold — new source IPs, unusual logins, sandboxed attachment detonations.", mitigate: "MFA, patching internet-facing services, email filtering and least-privilege access are the highest-value controls at this stage."),
        Technique("T1568", "Dynamic Resolution", ["TA0011"], "Adversaries may dynamically establish connections to command and control infrastructure to evade common detections and remediations. This may be achieved by using malware that shares a common algorithm with the infrastructure the adversary uses to receive the malware's communications. These calculations can be used to dynamically adjust parameters such as the domain name, IP address, or port number the malware uses for command and control.", detect: "Beaconing analysis, DNS/TLS anomalies and egress monitoring catch C2 channels trying to blend into normal traffic.", mitigate: "Egress filtering, proxy inspection and blocking known C2 infrastructure are the main levers here."),
        Technique("T1667", "Email Bombing", ["TA0040"], "Adversaries may flood targeted email addresses with an overwhelming volume of messages. This may bury legitimate emails in a flood of spam and disrupt business operations.", detect: "Mass file writes/deletes/renames, shadow-copy deletion, and unexpected shutdown/reboot events are late-stage, high-confidence signals.", mitigate: "Offline backups, least privilege and EDR are the last line of defence once an adversary reaches this stage."),
        Technique("T1114", "Email Collection", ["TA0009"], "Adversaries may target user email to collect sensitive information. Emails may contain sensitive data, including trade secrets or personal information, that can prove valuable to adversaries. Emails may also contain details of ongoing incident response operations, which may allow adversaries to adjust their techniques in order to maintain persistence or evade defenses. Adversaries can collect or forward email from mail servers or clients.", detect: "Mass file access, staging directories, and bulk reads across many hosts are typical before data is moved out.", mitigate: "DLP, least privilege and encryption at rest limit what's useful to an adversary even if collection succeeds."),
        Technique("T1573", "Encrypted Channel", ["TA0011"], "Adversaries may employ an encryption algorithm to conceal command and control traffic rather than relying on any inherent protections provided by a communication protocol. Despite the use of a secure algorithm, these implementations may be vulnerable to reverse engineering if secret keys are encoded and/or generated within malware samples/configuration files.", detect: "Beaconing analysis, DNS/TLS anomalies and egress monitoring catch C2 channels trying to blend into normal traffic.", mitigate: "Egress filtering, proxy inspection and blocking known C2 infrastructure are the main levers here."),
        Technique("T1499", "Endpoint Denial of Service", ["TA0040"], "Adversaries may perform Endpoint Denial of Service (DoS) attacks to degrade or block the availability of services to users. Endpoint DoS can be performed by exhausting the system resources those services are hosted on or exploiting the system to cause a persistent crash condition. Example services include websites, email services, DNS, and web-based applications. Adversaries have been observed conducting DoS attacks for political purposes and to support other malicious activities, including distraction, hacktivism, and extortion.", detect: "Mass file writes/deletes/renames, shadow-copy deletion, and unexpected shutdown/reboot events are late-stage, high-confidence signals.", mitigate: "Offline backups, least privilege and EDR are the last line of defence once an adversary reaches this stage."),
        Technique("T1611", "Escape to Host", ["TA0004"], "Adversaries may break out of a container or virtualized environment to gain access to the underlying host. This can allow an adversary access to other containerized or virtualized resources from the host level or to the host itself. In principle, containerized / virtualized resources should provide a clear separation of application functionality and be isolated from the host environment.", detect: "EDR telemetry around exploit attempts, sudo/UAC bypass patterns, and unexpected token/process manipulation are the main signals.", mitigate: "Patch known escalation vulnerabilities, enforce least privilege, and keep elevation mechanisms (UAC, sudoers) tightly configured."),
        Technique("T1585", "Establish Accounts", ["TA0042"], "Adversaries may create and cultivate accounts with services that can be used during targeting. Adversaries can create accounts that can be used to build a persona to further operations. Persona development consists of the development of public information, presence, history and appropriate affiliations. This development could be applied to social media, website, or other publicly available information that could be referenced and scrutinized for legitimacy over the course of an operation using that persona or identity.", detect: "Happens on adversary-controlled infrastructure, so it's invisible to your monitoring; rely on threat-intel feeds for newly-registered domains/certificates tied to known campaigns.", mitigate: "Block or flag indicators from threat-intel feeds (new domains, abused certificates) before they're used against you."),
        Technique("T1675", "ESXi Administration Command", ["TA0002"], "Adversaries may abuse ESXi administration services to execute commands on guest machines hosted within an ESXi virtual environment. Persistent background services on ESXi-hosted VMs, such as the VMware Tools Daemon Service, allow for remote management from the ESXi server. The tools daemon service runs as vmtoolsd.exe on Windows guest operating systems, vmware-tools-daemon on macOS, and vmtoolsd on Linux.", detect: "Process and command-line logging (EDR, PowerShell/Bash logging) catches most execution techniques as they run.", mitigate: "Application allowlisting and constrained scripting environments reduce what an adversary can execute even after they get in."),
        Technique("T1546", "Event Triggered Execution", ["TA0003", "TA0004"], "Adversaries may establish persistence and/or elevate privileges using system mechanisms that trigger execution based on specific events. Various operating systems have means to monitor and subscribe to events such as logons or other user activity such as running specific applications/binaries. Cloud environments may also support various functions and services that monitor and can be invoked in response to specific cloud events.", detect: "Monitor for new services, scheduled tasks, startup entries and account/key changes — persistence usually leaves a durable artifact.", mitigate: "Least privilege, restricting who can create services/tasks/accounts, and regular audits of autostart locations close most persistence paths."),
        Technique("T1668", "Exclusive Control", ["TA0003"], "Adversaries who successfully compromise a system may attempt to maintain persistence by \"closing the door\" behind them – in other words, by preventing other threat actors from initially accessing or maintaining a foothold on the same system.", detect: "Monitor for new services, scheduled tasks, startup entries and account/key changes — persistence usually leaves a durable artifact.", mitigate: "Least privilege, restricting who can create services/tasks/accounts, and regular audits of autostart locations close most persistence paths."),
        Technique("T1480", "Execution Guardrails", ["TA0005"], "Adversaries may use execution guardrails to constrain execution or actions based on adversary supplied and environment specific conditions that are expected to be present on the target. Guardrails ensure that a payload only executes against an intended target and reduces collateral damage from an adversary’s campaign. Values an adversary can provide about a target system or environment to use as guardrails may include specific network share names, attached physical devices, files, joined Active Directory (AD) domains, and local/external IP addresses.", detect: "Behavioural/EDR detection and centralised logging matter here, since the goal is to blend in or hide rather than be loud.", mitigate: "Forward logs off-host, use application control, and favour behavioural over signature-based detection so evading one layer doesn't mean invisibility."),
        Technique("T1048", "Exfiltration Over Alternative Protocol", ["TA0010"], "Adversaries may steal data by exfiltrating it over a different protocol than that of the existing command and control channel. The data may also be sent to an alternate network location from the main command and control server.", detect: "Outbound volume anomalies and uploads to unsanctioned cloud/web services are the main signal.", mitigate: "DLP, egress limits and blocking/allowlisting web services reduce how data can leave undetected."),
        Technique("T1041", "Exfiltration Over C2 Channel", ["TA0010"], "Adversaries may steal data by exfiltrating it over an existing command and control channel. Stolen data is encoded into the normal communications channel using the same protocol as command and control communications.", detect: "Outbound volume anomalies and uploads to unsanctioned cloud/web services are the main signal.", mitigate: "DLP, egress limits and blocking/allowlisting web services reduce how data can leave undetected."),
        Technique("T1011", "Exfiltration Over Other Network Medium", ["TA0010"], "Adversaries may attempt to exfiltrate data over a different network medium than the command and control channel. If the command and control network is a wired Internet connection, the exfiltration may occur, for example, over a WiFi connection, modem, cellular data connection, Bluetooth, or another radio frequency (RF) channel.", detect: "Outbound volume anomalies and uploads to unsanctioned cloud/web services are the main signal.", mitigate: "DLP, egress limits and blocking/allowlisting web services reduce how data can leave undetected."),
        Technique("T1052", "Exfiltration Over Physical Medium", ["TA0010"], "Adversaries may attempt to exfiltrate data via a physical medium, such as a removable drive. In certain circumstances, such as an air-gapped network compromise, exfiltration could occur via a physical medium or device introduced by a user. Such media could be an external hard drive, USB drive, cellular phone, MP3 player, or other removable storage and processing device. The physical medium or device could be used as the final exfiltration point or to hop between otherwise disconnected systems.", detect: "Outbound volume anomalies and uploads to unsanctioned cloud/web services are the main signal.", mitigate: "DLP, egress limits and blocking/allowlisting web services reduce how data can leave undetected."),
        Technique("T1567", "Exfiltration Over Web Service", ["TA0010"], "Adversaries may use an existing, legitimate external Web service to exfiltrate data rather than their primary command and control channel. Popular Web services acting as an exfiltration mechanism may give a significant amount of cover due to the likelihood that hosts within a network are already communicating with them prior to compromise. Firewall rules may also already exist to permit traffic to these services.", detect: "Outbound volume anomalies and uploads to unsanctioned cloud/web services are the main signal.", mitigate: "DLP, egress limits and blocking/allowlisting web services reduce how data can leave undetected."),
        Technique("T1190", "Exploit Public-Facing Application", ["TA0001"], "Adversaries may attempt to exploit a weakness in an Internet-facing host or system to initially access a network. The weakness in the system can be a software bug, a temporary glitch, or a misconfiguration.", detect: "Watch authentication logs, email gateways and perimeter IDS/WAF for the first foothold — new source IPs, unusual logins, sandboxed attachment detonations.", mitigate: "MFA, patching internet-facing services, email filtering and least-privilege access are the highest-value controls at this stage."),
        Technique("T1203", "Exploitation for Client Execution", ["TA0002"], "Adversaries may exploit software vulnerabilities in client applications to execute code. Vulnerabilities can exist in software due to unsecure coding practices that can lead to unanticipated behavior. Adversaries can take advantage of certain vulnerabilities through targeted exploitation for the purpose of arbitrary code execution. Oftentimes the most valuable exploits to an offensive toolkit are those that can be used to obtain code execution on a remote system because they can be used to gain access to that system. Users will expect to see files related to the applications they commonly used to do work, so they are a useful target for exploit research and development because of their high utility.", detect: "Process and command-line logging (EDR, PowerShell/Bash logging) catches most execution techniques as they run.", mitigate: "Application allowlisting and constrained scripting environments reduce what an adversary can execute even after they get in."),
        Technique("T1212", "Exploitation for Credential Access", ["TA0006"], "Adversaries may exploit software vulnerabilities in an attempt to collect credentials. Exploitation of a software vulnerability occurs when an adversary takes advantage of a programming error in a program, service, or within the operating system software or kernel itself to execute adversary-controlled code.", detect: "Failed-login spikes, LSASS/SAM/shadow access, and access to credential stores (browsers, password managers) are the classic signals.", mitigate: "MFA, credential-guard/LAPS-style protections, secret scanning and rotating any exposed credential are the highest-value controls."),
        Technique("T1687", "Exploitation for Defense Impairment", ["TA0112"], "Adversaries may exploit vulnerabilities in security software, infrastructure, or defensive components to degrade, disable, or otherwise continue to impair their ability to prevent, detect, or respond to malicious activity.", detect: "Alert on any attempt to disable, reconfigure or tamper with security tooling itself (AV/EDR stopped, logging turned off, firewall rules changed) — these are high-confidence signals on their own.", mitigate: "Tamper-protect security agents, centralise logs off-host, and treat any successful tampering attempt as an incident regardless of what else is seen."),
        Technique("T1068", "Exploitation for Privilege Escalation", ["TA0004"], "Adversaries may exploit software vulnerabilities in an attempt to elevate privileges. Exploitation of a software vulnerability occurs when an adversary takes advantage of a programming error in a program, service, or within the operating system software or kernel itself to execute adversary-controlled code. Security constructs such as permission levels will often hinder access to information and use of certain techniques, so adversaries will likely need to perform privilege escalation to include use of software exploitation to circumvent those restrictions.", detect: "EDR telemetry around exploit attempts, sudo/UAC bypass patterns, and unexpected token/process manipulation are the main signals.", mitigate: "Patch known escalation vulnerabilities, enforce least privilege, and keep elevation mechanisms (UAC, sudoers) tightly configured."),
        Technique("T1211", "Exploitation for Stealth", ["TA0005"], "Adversaries may exploit vulnerabilities to evade detection by hiding activity, suppressing logging, or operating within trusted or unmonitored components.", detect: "Behavioural/EDR detection and centralised logging matter here, since the goal is to blend in or hide rather than be loud.", mitigate: "Forward logs off-host, use application control, and favour behavioural over signature-based detection so evading one layer doesn't mean invisibility."),
        Technique("T1210", "Exploitation of Remote Services", ["TA0008"], "Adversaries may exploit remote services to gain unauthorized access to internal systems once inside of a network. Exploitation of a software vulnerability occurs when an adversary takes advantage of a programming error in a program, service, or within the operating system software or kernel itself to execute adversary-controlled code. A common goal for post-compromise exploitation of remote services is for lateral movement to enable access to a remote system.", detect: "New admin sessions, unusual authentication patterns between hosts, and file transfers to admin shares are the key signals.", mitigate: "MFA, network segmentation, and restricting admin protocols (RDP/SMB/WinRM) between zones limit how far a foothold can spread."),
        Technique("T1133", "External Remote Services", ["TA0001", "TA0003"], "Adversaries may leverage external-facing remote services to initially access and/or persist within a network. Remote services such as VPNs, Citrix, and other access mechanisms allow users to connect to internal enterprise network resources from external locations. There are often remote service gateways that manage connections and credential authentication for these services. Services such as Windows Remote Management and VNC can also be used externally.", detect: "Watch authentication logs, email gateways and perimeter IDS/WAF for the first foothold — new source IPs, unusual logins, sandboxed attachment detonations.", mitigate: "MFA, patching internet-facing services, email filtering and least-privilege access are the highest-value controls at this stage."),
        Technique("T1008", "Fallback Channels", ["TA0011"], "Adversaries may use fallback or alternate communication channels if the primary channel is compromised or inaccessible in order to maintain reliable command and control and to avoid data transfer thresholds.", detect: "Beaconing analysis, DNS/TLS anomalies and egress monitoring catch C2 channels trying to blend into normal traffic.", mitigate: "Egress filtering, proxy inspection and blocking known C2 infrastructure are the main levers here."),
        Technique("T1083", "File and Directory Discovery", ["TA0007"], "Adversaries may enumerate files and directories or may search in specific locations of a host or network share for certain information within a file system. Adversaries may use the information from File and Directory Discovery during automated discovery to shape follow-on behaviors, including whether or not the adversary fully infects the target and/or attempts specific actions.", detect: "Bursts of enumeration commands (whoami, net user, ipconfig, AD queries) in a short window from one host are the giveaway.", mitigate: "Segmentation and limiting discovery-protocol exposure won't stop discovery outright but slows and narrows what's learned."),
        Technique("T1222", "File and Directory Permissions Modification", ["TA0112"], "Adversaries may modify file or directory permissions/attributes to evade access control lists (ACLs) and access protected files. File and directory permissions are commonly managed by ACLs configured by the file or directory owner, or users with the appropriate permissions. File and directory ACL implementations vary by platform, but generally explicitly designate which users or groups can perform which actions (read, write, execute, etc.).", detect: "Alert on any attempt to disable, reconfigure or tamper with security tooling itself (AV/EDR stopped, logging turned off, firewall rules changed) — these are high-confidence signals on their own.", mitigate: "Tamper-protect security agents, centralise logs off-host, and treat any successful tampering attempt as an incident regardless of what else is seen."),
        Technique("T1657", "Financial Theft", ["TA0040"], "Adversaries may steal monetary resources from targets through extortion, social engineering, technical theft, or other methods aimed at their own financial gain at the expense of the availability of these resources for victims. Financial theft is the ultimate objective of several popular campaign types including extortion by ransomware, business email compromise (BEC) and fraud, \"pig butchering,\" bank hacking, and exploiting cryptocurrency networks.", detect: "Mass file writes/deletes/renames, shadow-copy deletion, and unexpected shutdown/reboot events are late-stage, high-confidence signals.", mitigate: "Offline backups, least privilege and EDR are the last line of defence once an adversary reaches this stage."),
        Technique("T1495", "Firmware Corruption", ["TA0040"], "Adversaries may overwrite or corrupt the flash memory contents of system BIOS or other firmware in devices attached to a system in order to render them inoperable or unable to boot, thus denying the availability to use the devices and/or the system. Firmware is software that is loaded and executed from non-volatile memory on hardware devices in order to initialize and manage device functionality. These devices may include the motherboard, hard drive, or video cards.", detect: "Mass file writes/deletes/renames, shadow-copy deletion, and unexpected shutdown/reboot events are late-stage, high-confidence signals.", mitigate: "Offline backups, least privilege and EDR are the last line of defence once an adversary reaches this stage."),
        Technique("T1187", "Forced Authentication", ["TA0006"], "Adversaries may gather credential material by invoking or forcing a user to automatically provide authentication information through a mechanism in which they can intercept.", detect: "Failed-login spikes, LSASS/SAM/shadow access, and access to credential stores (browsers, password managers) are the classic signals.", mitigate: "MFA, credential-guard/LAPS-style protections, secret scanning and rotating any exposed credential are the highest-value controls."),
        Technique("T1606", "Forge Web Credentials", ["TA0006"], "Adversaries may forge credential materials that can be used to gain access to web applications or Internet services. Web applications and services (hosted in cloud SaaS environments or on-premise servers) often use session cookies, tokens, or other materials to authenticate and authorize user access.", detect: "Failed-login spikes, LSASS/SAM/shadow access, and access to credential stores (browsers, password managers) are the classic signals.", mitigate: "MFA, credential-guard/LAPS-style protections, secret scanning and rotating any exposed credential are the highest-value controls."),
        Technique("T1592", "Gather Victim Host Information", ["TA0043"], "Adversaries may gather information about the victim's hosts that can be used during targeting. Information about hosts may include a variety of details, including administrative data (ex: name, assigned IP, functionality, etc.) as well as specifics regarding its configuration (ex: operating system, language, etc.).", detect: "Largely pre-compromise and hard to see from inside your network; watch for scanning noise against your assets and monitor your own exposure in Shodan/Censys/CT logs.", mitigate: "Minimise what's publicly discoverable (banners, WHOIS, exposed services) — this stage is about reducing attack surface, not stopping the adversary directly."),
        Technique("T1589", "Gather Victim Identity Information", ["TA0043"], "Adversaries may gather information about the victim's identity that can be used during targeting. Information about identities may include a variety of details, including personal data (ex: employee names, email addresses, security question responses, etc.) as well as sensitive details such as credentials or multi-factor authentication (MFA) configurations.", detect: "Largely pre-compromise and hard to see from inside your network; watch for scanning noise against your assets and monitor your own exposure in Shodan/Censys/CT logs.", mitigate: "Minimise what's publicly discoverable (banners, WHOIS, exposed services) — this stage is about reducing attack surface, not stopping the adversary directly."),
        Technique("T1590", "Gather Victim Network Information", ["TA0043"], "Adversaries may gather information about the victim's networks that can be used during targeting. Information about networks may include a variety of details, including administrative data (ex: IP ranges, domain names, etc.) as well as specifics regarding its topology and operations.", detect: "Largely pre-compromise and hard to see from inside your network; watch for scanning noise against your assets and monitor your own exposure in Shodan/Censys/CT logs.", mitigate: "Minimise what's publicly discoverable (banners, WHOIS, exposed services) — this stage is about reducing attack surface, not stopping the adversary directly."),
        Technique("T1591", "Gather Victim Org Information", ["TA0043"], "Adversaries may gather information about the victim's organization that can be used during targeting. Information about an organization may include a variety of details, including the names of divisions/departments, specifics of business operations, as well as the roles and responsibilities of key employees.", detect: "Largely pre-compromise and hard to see from inside your network; watch for scanning noise against your assets and monitor your own exposure in Shodan/Censys/CT logs.", mitigate: "Minimise what's publicly discoverable (banners, WHOIS, exposed services) — this stage is about reducing attack surface, not stopping the adversary directly."),
        Technique("T1683", "Generate Content", ["TA0042"], "Adversaries may create or generate content to support targeting and operations. This content may be used to establish personas, impersonate known individuals or organizations, and support Social Engineering, fraud, or influence activities. Written materials, audio, images, video, or other media may be developed and tailored to the target and objective.", detect: "Happens on adversary-controlled infrastructure, so it's invisible to your monitoring; rely on threat-intel feeds for newly-registered domains/certificates tied to known campaigns.", mitigate: "Block or flag indicators from threat-intel feeds (new domains, abused certificates) before they're used against you."),
        Technique("T1615", "Group Policy Discovery", ["TA0007"], "Adversaries may gather information on Group Policy settings to identify paths for privilege escalation, security measures applied within a domain, and to discover patterns in domain objects that can be manipulated or used to blend in the environment. Group Policy allows for centralized management of user and computer settings in Active Directory (AD). Group policy objects (GPOs) are containers for group policy settings made up of files stored within a predictable network path \\<DOMAIN>\\SYSVOL\\<DOMAIN>\\Policies\\.", detect: "Bursts of enumeration commands (whoami, net user, ipconfig, AD queries) in a short window from one host are the giveaway.", mitigate: "Segmentation and limiting discovery-protocol exposure won't stop discovery outright but slows and narrows what's learned."),
        Technique("T1200", "Hardware Additions", ["TA0001"], "Adversaries may physically introduce computer accessories, networking hardware, or other computing devices into a system or network that can be used as a vector to gain access. Rather than just connecting and distributing payloads via removable storage (i.e. Replication Through Removable Media), more robust hardware additions can be used to introduce new functionalities and/or features into a system that can then be abused.", detect: "Watch authentication logs, email gateways and perimeter IDS/WAF for the first foothold — new source IPs, unusual logins, sandboxed attachment detonations.", mitigate: "MFA, patching internet-facing services, email filtering and least-privilege access are the highest-value controls at this stage."),
        Technique("T1564", "Hide Artifacts", ["TA0005"], "Adversaries may attempt to hide artifacts associated with their behaviors to evade detection. Operating systems may have features to hide various artifacts, such as important system files and administrative task execution, to avoid disrupting user work environments and prevent users from changing files or features on the system. Adversaries may abuse these features to hide artifacts such as files, directories, user accounts, or other system activity to evade detection.", detect: "Behavioural/EDR detection and centralised logging matter here, since the goal is to blend in or hide rather than be loud.", mitigate: "Forward logs off-host, use application control, and favour behavioural over signature-based detection so evading one layer doesn't mean invisibility."),
        Technique("T1665", "Hide Infrastructure", ["TA0011"], "Adversaries may manipulate network traffic in order to hide and evade detection of their C2 infrastructure. This can be accomplished by identifying and filtering traffic from defensive tools, masking malicious domains to obfuscate the true destination from both automated scanning tools and security researchers, and otherwise hiding malicious artifacts to delay discovery and prolong the effectiveness of adversary infrastructure that could otherwise be identified, blocked, or taken down entirely.", detect: "Beaconing analysis, DNS/TLS anomalies and egress monitoring catch C2 channels trying to blend into normal traffic.", mitigate: "Egress filtering, proxy inspection and blocking known C2 infrastructure are the main levers here."),
        Technique("T1574", "Hijack Execution Flow", ["TA0002", "TA0005"], "Adversaries may execute their own malicious payloads by hijacking the way operating systems run programs. Hijacking execution flow can be for the purposes of persistence, since this hijacked execution may reoccur over time. Adversaries may also use these mechanisms to elevate privileges or evade defenses, such as application control or other restrictions on execution.", detect: "Process and command-line logging (EDR, PowerShell/Bash logging) catches most execution techniques as they run.", mitigate: "Application allowlisting and constrained scripting environments reduce what an adversary can execute even after they get in."),
        Technique("T1525", "Implant Internal Image", ["TA0003"], "Adversaries may implant cloud or container images with malicious code to establish persistence after gaining access to an environment. Amazon Web Services (AWS) Amazon Machine Images (AMIs), Google Cloud Platform (GCP) Images, and Azure Images as well as popular container runtimes such as Docker can be implanted or backdoored. Unlike Upload Malware, this technique focuses on adversaries implanting an image in a registry within a victim’s environment. Depending on how the infrastructure is provisioned, this could provide persistent access if the infrastructure provisioning tool is instructed to always use the latest image.", detect: "Monitor for new services, scheduled tasks, startup entries and account/key changes — persistence usually leaves a durable artifact.", mitigate: "Least privilege, restricting who can create services/tasks/accounts, and regular audits of autostart locations close most persistence paths."),
        Technique("T1070", "Indicator Removal", ["TA0005"], "Adversaries may selectively delete or modify artifacts generated to reduce indications of their presence and blend in with legitimate activity. Rather than broadly removing evidence, adversaries may target specific artifacts that appear anomalous or are likely to draw scrutiny, while leaving sufficient data intact to maintain the appearance of normal system behavior.", detect: "Behavioural/EDR detection and centralised logging matter here, since the goal is to blend in or hide rather than be loud.", mitigate: "Forward logs off-host, use application control, and favour behavioural over signature-based detection so evading one layer doesn't mean invisibility."),
        Technique("T1202", "Indirect Command Execution", ["TA0005"], "Adversaries may abuse utilities that allow for command execution to bypass security restrictions that limit the use of command-line interpreters. Various Windows utilities may be used to execute commands, possibly without invoking cmd. For example, Forfiles, the Program Compatibility Assistant (pcalua.exe), components of the Windows Subsystem for Linux (WSL), Scriptrunner.exe, as well as other utilities may invoke the execution of programs and commands from a Command and Scripting Interpreter, Run window, or via scripts. Adversaries may also abuse the ssh.exe binary to execute malicious commands via the ProxyCommand and LocalCommand options, which can be invoked via the -o flag or by modifying the SSH config file.", detect: "Behavioural/EDR detection and centralised logging matter here, since the goal is to blend in or hide rather than be loud.", mitigate: "Forward logs off-host, use application control, and favour behavioural over signature-based detection so evading one layer doesn't mean invisibility."),
        Technique("T1698", "Indirect Prompt Injection", ["TA0002"], "Adversaries may deliver malicious prompts to an LLM indirectly by embedding the prompts in content that the adversary expects may be processed by an LLM. These prompts can be included in web pages, documents, emails, tickets, code, or other sources that an agent, copilot, or other AI system may retrieve and process. When an LLM processes this content, the embedded instructions may cause the system to perform unintended behaviors.", detect: "Process and command-line logging (EDR, PowerShell/Bash logging) catches most execution techniques as they run.", mitigate: "Application allowlisting and constrained scripting environments reduce what an adversary can execute even after they get in."),
        Technique("T1105", "Ingress Tool Transfer", ["TA0011"], "Adversaries may transfer tools or other files from an external system into a compromised environment. Tools or files may be copied from an external adversary-controlled system to the victim network through the command and control channel or through alternate protocols such as ftp. Once present, adversaries may also transfer/spread tools between victim devices within a compromised environment (i.e. Lateral Tool Transfer).", detect: "Beaconing analysis, DNS/TLS anomalies and egress monitoring catch C2 channels trying to blend into normal traffic.", mitigate: "Egress filtering, proxy inspection and blocking known C2 infrastructure are the main levers here."),
        Technique("T1490", "Inhibit System Recovery", ["TA0040"], "Adversaries may delete or remove built-in data and turn off services designed to aid in the recovery of a corrupted system to prevent recovery. This may deny access to available backups and recovery options.", detect: "Mass file writes/deletes/renames, shadow-copy deletion, and unexpected shutdown/reboot events are late-stage, high-confidence signals.", mitigate: "Offline backups, least privilege and EDR are the last line of defence once an adversary reaches this stage."),
        Technique("T1056", "Input Capture", ["TA0006", "TA0009"], "Adversaries may use methods of capturing user input to obtain credentials or collect information. During normal system usage, users often provide credentials to various different locations, such as login pages/portals or system dialog boxes. Input capture mechanisms may be transparent to the user (e.g. Credential API Hooking) or rely on deceiving the user into providing input into what they believe to be a genuine service (e.g. Web Portal Capture).", detect: "Failed-login spikes, LSASS/SAM/shadow access, and access to credential stores (browsers, password managers) are the classic signals.", mitigate: "MFA, credential-guard/LAPS-style protections, secret scanning and rotating any exposed credential are the highest-value controls."),
        Technique("T1674", "Input Injection", ["TA0002"], "Adversaries may simulate keystrokes on a victim’s computer by various means to perform any type of action on behalf of the user, such as launching the command interpreter using keyboard shortcuts, typing an inline script to be executed, or interacting directly with a GUI-based application. These actions can be preprogrammed into adversary tooling or executed through physical devices such as Human Interface Devices (HIDs).", detect: "Process and command-line logging (EDR, PowerShell/Bash logging) catches most execution techniques as they run.", mitigate: "Application allowlisting and constrained scripting environments reduce what an adversary can execute even after they get in."),
        Technique("T1559", "Inter-Process Communication", ["TA0002"], "Adversaries may abuse inter-process communication (IPC) mechanisms for local code or command execution. IPC is typically used by processes to share data, communicate with each other, or synchronize execution. IPC is also commonly used to avoid situations such as deadlocks, which occurs when processes are stuck in a cyclic waiting pattern.", detect: "Process and command-line logging (EDR, PowerShell/Bash logging) catches most execution techniques as they run.", mitigate: "Application allowlisting and constrained scripting environments reduce what an adversary can execute even after they get in."),
        Technique("T1534", "Internal Spearphishing", ["TA0008"], "After they already have access to accounts or systems within the environment, adversaries may use internal spearphishing to gain access to additional information or compromise other users within the same organization. Internal spearphishing is multi-staged campaign where a legitimate account is initially compromised either by controlling the user's device or by compromising the account credentials of the user. Adversaries may then attempt to take advantage of the trusted internal account to increase the likelihood of tricking more victims into falling for phish attempts, often incorporating Impersonation.", detect: "New admin sessions, unusual authentication patterns between hosts, and file transfers to admin shares are the key signals.", mitigate: "MFA, network segmentation, and restricting admin protocols (RDP/SMB/WinRM) between zones limit how far a foothold can spread."),
        Technique("T1570", "Lateral Tool Transfer", ["TA0008"], "Adversaries may transfer tools or other files between systems in a compromised environment. Once brought into the victim environment (i.e., Ingress Tool Transfer) files may then be copied from one system to another to stage adversary tools or other files over the course of an operation.", detect: "New admin sessions, unusual authentication patterns between hosts, and file transfers to admin shares are the key signals.", mitigate: "MFA, network segmentation, and restricting admin protocols (RDP/SMB/WinRM) between zones limit how far a foothold can spread."),
        Technique("T1680", "Local Storage Discovery", ["TA0007"], "Adversaries may enumerate local drives, disks, and/or volumes and their attributes like total or free space and volume serial number. This can be done to prepare for ransomware-related encryption, to perform Lateral Movement, or as a precursor to Direct Volume Access.", detect: "Bursts of enumeration commands (whoami, net user, ipconfig, AD queries) in a short window from one host are the giveaway.", mitigate: "Segmentation and limiting discovery-protocol exposure won't stop discovery outright but slows and narrows what's learned."),
        Technique("T1654", "Log Enumeration", ["TA0007"], "Adversaries may enumerate system and service logs to find useful data. These logs may highlight various types of valuable insights for an adversary, such as user authentication records (Account Discovery), security or vulnerable software (Software Discovery), or hosts within a compromised network (Remote System Discovery).", detect: "Bursts of enumeration commands (whoami, net user, ipconfig, AD queries) in a short window from one host are the giveaway.", mitigate: "Segmentation and limiting discovery-protocol exposure won't stop discovery outright but slows and narrows what's learned."),
        Technique("T1036", "Masquerading", ["TA0005"], "Adversaries may attempt to manipulate features of their artifacts to make them appear legitimate or benign to users and/or security tools. Masquerading occurs when the name or location of an object, legitimate or malicious, is manipulated or abused for the sake of evading defenses and observation. This may include manipulating file metadata, tricking users into misidentifying the file type, and giving legitimate task or service names.", detect: "Behavioural/EDR detection and centralised logging matter here, since the goal is to blend in or hide rather than be loud.", mitigate: "Forward logs off-host, use application control, and favour behavioural over signature-based detection so evading one layer doesn't mean invisibility."),
        Technique("T1556", "Modify Authentication Process", ["TA0003", "TA0112", "TA0006"], "Adversaries may modify authentication mechanisms and processes to access user credentials or enable otherwise unwarranted access to accounts. The authentication process is handled by mechanisms, such as the Local Security Authentication Server (LSASS) process and the Security Accounts Manager (SAM) on Windows, pluggable authentication modules (PAM) on Unix-based systems, and authorization plugins on MacOS systems, responsible for gathering, storing, and validating credentials. By modifying an authentication process, an adversary may be able to authenticate to a service or system without using Valid Accounts.", detect: "Monitor for new services, scheduled tasks, startup entries and account/key changes — persistence usually leaves a durable artifact.", mitigate: "Least privilege, restricting who can create services/tasks/accounts, and regular audits of autostart locations close most persistence paths."),
        Technique("T1578", "Modify Cloud Compute Infrastructure", ["TA0112"], "An adversary may attempt to modify a cloud account's compute service infrastructure to evade defenses. A modification to the compute service infrastructure can include the creation, deletion, or modification of one or more components such as compute instances, virtual machines, and snapshots.", detect: "Alert on any attempt to disable, reconfigure or tamper with security tooling itself (AV/EDR stopped, logging turned off, firewall rules changed) — these are high-confidence signals on their own.", mitigate: "Tamper-protect security agents, centralise logs off-host, and treat any successful tampering attempt as an incident regardless of what else is seen."),
        Technique("T1666", "Modify Cloud Resource Hierarchy", ["TA0112"], "Adversaries may attempt to modify hierarchical structures in infrastructure-as-a-service (IaaS) environments in order to evade defenses.", detect: "Alert on any attempt to disable, reconfigure or tamper with security tooling itself (AV/EDR stopped, logging turned off, firewall rules changed) — these are high-confidence signals on their own.", mitigate: "Tamper-protect security agents, centralise logs off-host, and treat any successful tampering attempt as an incident regardless of what else is seen."),
        Technique("T1112", "Modify Registry", ["TA0003", "TA0112"], "Adversaries may interact with the Windows Registry as part of a variety of other techniques to aid in defense evasion, persistence, and execution.", detect: "Monitor for new services, scheduled tasks, startup entries and account/key changes — persistence usually leaves a durable artifact.", mitigate: "Least privilege, restricting who can create services/tasks/accounts, and regular audits of autostart locations close most persistence paths."),
        Technique("T1601", "Modify System Image", ["TA0112"], "Adversaries may make changes to the operating system of embedded network devices to weaken defenses and provide new capabilities for themselves. On such devices, the operating systems are typically monolithic and most of the device functionality and capabilities are contained within a single file.", detect: "Alert on any attempt to disable, reconfigure or tamper with security tooling itself (AV/EDR stopped, logging turned off, firewall rules changed) — these are high-confidence signals on their own.", mitigate: "Tamper-protect security agents, centralise logs off-host, and treat any successful tampering attempt as an incident regardless of what else is seen."),
        Technique("T1111", "Multi-Factor Authentication Interception", ["TA0006"], "Adversaries may target multi-factor authentication (MFA) mechanisms, (i.e., smart cards, token generators, etc.) to gain access to credentials that can be used to access systems, services, and network resources. Use of MFA is recommended and provides a higher level of security than usernames and passwords alone, but organizations should be aware of techniques that could be used to intercept and bypass these security mechanisms.", detect: "Failed-login spikes, LSASS/SAM/shadow access, and access to credential stores (browsers, password managers) are the classic signals.", mitigate: "MFA, credential-guard/LAPS-style protections, secret scanning and rotating any exposed credential are the highest-value controls."),
        Technique("T1621", "Multi-Factor Authentication Request Generation", ["TA0006"], "Adversaries may attempt to bypass multi-factor authentication (MFA) mechanisms and gain access to accounts by generating MFA requests sent to users.", detect: "Failed-login spikes, LSASS/SAM/shadow access, and access to credential stores (browsers, password managers) are the classic signals.", mitigate: "MFA, credential-guard/LAPS-style protections, secret scanning and rotating any exposed credential are the highest-value controls."),
        Technique("T1104", "Multi-Stage Channels", ["TA0011"], "Adversaries may create multiple stages for command and control that are employed under different conditions or for certain functions. Use of multiple stages may obfuscate the command and control channel to make detection more difficult.", detect: "Beaconing analysis, DNS/TLS anomalies and egress monitoring catch C2 channels trying to blend into normal traffic.", mitigate: "Egress filtering, proxy inspection and blocking known C2 infrastructure are the main levers here."),
        Technique("T1106", "Native API", ["TA0002"], "Adversaries may interact with the native OS application programming interface (API) to execute behaviors. Native APIs provide a controlled means of calling low-level OS services within the kernel, such as those involving hardware/devices, memory, and processes. These native APIs are leveraged by the OS during system boot (when other system components are not yet initialized) as well as carrying out tasks and requests during routine operations.", detect: "Process and command-line logging (EDR, PowerShell/Bash logging) catches most execution techniques as they run.", mitigate: "Application allowlisting and constrained scripting environments reduce what an adversary can execute even after they get in."),
        Technique("T1599", "Network Boundary Bridging", ["TA0112"], "Adversaries may bridge network boundaries by compromising perimeter network devices or internal devices responsible for network segmentation. Breaching these devices may enable an adversary to bypass restrictions on traffic routing that otherwise separate trusted and untrusted networks.", detect: "Alert on any attempt to disable, reconfigure or tamper with security tooling itself (AV/EDR stopped, logging turned off, firewall rules changed) — these are high-confidence signals on their own.", mitigate: "Tamper-protect security agents, centralise logs off-host, and treat any successful tampering attempt as an incident regardless of what else is seen."),
        Technique("T1498", "Network Denial of Service", ["TA0040"], "Adversaries may perform Network Denial of Service (DoS) attacks to degrade or block the availability of targeted resources to users. Network DoS can be performed by exhausting the network bandwidth services rely on. Example resources include specific websites, email services, DNS, and web-based applications. Adversaries have been observed conducting network DoS attacks for political purposes and to support other malicious activities, including distraction, hacktivism, and extortion.", detect: "Mass file writes/deletes/renames, shadow-copy deletion, and unexpected shutdown/reboot events are late-stage, high-confidence signals.", mitigate: "Offline backups, least privilege and EDR are the last line of defence once an adversary reaches this stage."),
        Technique("T1046", "Network Service Discovery", ["TA0007"], "Adversaries may attempt to get a listing of services running on remote hosts and local network infrastructure devices, including those that may be vulnerable to remote software exploitation. Common methods to acquire this information include port, vulnerability, and/or wordlist scans using tools that are brought onto a system.", detect: "Bursts of enumeration commands (whoami, net user, ipconfig, AD queries) in a short window from one host are the giveaway.", mitigate: "Segmentation and limiting discovery-protocol exposure won't stop discovery outright but slows and narrows what's learned."),
        Technique("T1135", "Network Share Discovery", ["TA0007"], "Adversaries may look for folders and drives shared on remote systems as a means of identifying sources of information to gather as a precursor for Collection and to identify potential systems of interest for Lateral Movement. Networks often contain shared network drives and folders that enable users to access file directories on various systems across a network.", detect: "Bursts of enumeration commands (whoami, net user, ipconfig, AD queries) in a short window from one host are the giveaway.", mitigate: "Segmentation and limiting discovery-protocol exposure won't stop discovery outright but slows and narrows what's learned."),
        Technique("T1040", "Network Sniffing", ["TA0006", "TA0007"], "Adversaries may passively sniff network traffic to capture information about an environment, including authentication material passed over the network. Network sniffing refers to using the network interface on a system to monitor or capture information sent over a wired or wireless connection. An adversary may place a network interface into promiscuous mode to passively access data in transit over the network, or use span ports to capture a larger amount of data.", detect: "Failed-login spikes, LSASS/SAM/shadow access, and access to credential stores (browsers, password managers) are the classic signals.", mitigate: "MFA, credential-guard/LAPS-style protections, secret scanning and rotating any exposed credential are the highest-value controls."),
        Technique("T1095", "Non-Application Layer Protocol", ["TA0011"], "Adversaries may use an OSI non-application layer protocol for communication between host and C2 server or among infected hosts within a network. The list of possible protocols is extensive. Specific examples include use of network layer protocols, such as the Internet Control Message Protocol (ICMP), transport layer protocols, such as the User Datagram Protocol (UDP), session layer protocols, such as Socket Secure (SOCKS), as well as redirected/tunneled protocols, such as Serial over LAN (SOL).", detect: "Beaconing analysis, DNS/TLS anomalies and egress monitoring catch C2 channels trying to blend into normal traffic.", mitigate: "Egress filtering, proxy inspection and blocking known C2 infrastructure are the main levers here."),
        Technique("T1571", "Non-Standard Port", ["TA0011"], "Adversaries may communicate using a protocol and port pairing that are typically not associated. For example, HTTPS over port 8088 or port 587 as opposed to the traditional port 443. Adversaries may make changes to the standard port used by a protocol to bypass filtering or muddle analysis/parsing of network data.", detect: "Beaconing analysis, DNS/TLS anomalies and egress monitoring catch C2 channels trying to blend into normal traffic.", mitigate: "Egress filtering, proxy inspection and blocking known C2 infrastructure are the main levers here."),
        Technique("T1027", "Obfuscated Files or Information", ["TA0005"], "Adversaries may attempt to make an executable or file difficult to discover or analyze by encrypting, encoding, or otherwise obfuscating its contents on the system or in transit. This is common behavior that can be used across different platforms and the network to evade defenses.", detect: "Behavioural/EDR detection and centralised logging matter here, since the goal is to blend in or hide rather than be loud.", mitigate: "Forward logs off-host, use application control, and favour behavioural over signature-based detection so evading one layer doesn't mean invisibility."),
        Technique("T1588", "Obtain Capabilities", ["TA0042"], "Adversaries may buy and/or steal capabilities that can be used during targeting. Rather than developing their own capabilities in-house, adversaries may purchase, freely download, or steal them. Activities may include the acquisition of malware, software (including licenses), exploits, certificates, and information relating to vulnerabilities. Adversaries may obtain capabilities to support their operations throughout numerous phases of the adversary lifecycle.", detect: "Happens on adversary-controlled infrastructure, so it's invisible to your monitoring; rely on threat-intel feeds for newly-registered domains/certificates tied to known campaigns.", mitigate: "Block or flag indicators from threat-intel feeds (new domains, abused certificates) before they're used against you."),
        Technique("T1137", "Office Application Startup", ["TA0003"], "Adversaries may leverage Microsoft Office-based applications for persistence between startups. Microsoft Office is a fairly common application suite on Windows-based operating systems within an enterprise network. There are multiple mechanisms that can be used with Office for persistence when an Office-based application is started; this can include the use of Office Template Macros and add-ins.", detect: "Monitor for new services, scheduled tasks, startup entries and account/key changes — persistence usually leaves a durable artifact.", mitigate: "Least privilege, restricting who can create services/tasks/accounts, and regular audits of autostart locations close most persistence paths."),
        Technique("T1003", "OS Credential Dumping", ["TA0006"], "Adversaries may attempt to dump credentials to obtain account login and credential material, normally in the form of a hash or a clear text password. Credentials can be obtained from OS caches, memory, or structures. Credentials can then be used to perform Lateral Movement and access restricted information.", detect: "Failed-login spikes, LSASS/SAM/shadow access, and access to credential stores (browsers, password managers) are the classic signals.", mitigate: "MFA, credential-guard/LAPS-style protections, secret scanning and rotating any exposed credential are the highest-value controls."),
        Technique("T1201", "Password Policy Discovery", ["TA0007"], "Adversaries may attempt to access detailed information about the password policy used within an enterprise network or cloud environment. Password policies are a way to enforce complex passwords that are difficult to guess or crack through Brute Force. This information may help the adversary to create a list of common passwords and launch dictionary and/or brute force attacks which adheres to the policy (e.g. if the minimum password length should be 8, then not trying passwords such as 'pass123'; not checking for more than 3-4 passwords per account if the lockout is set to 6 as to not lock out accounts).", detect: "Bursts of enumeration commands (whoami, net user, ipconfig, AD queries) in a short window from one host are the giveaway.", mitigate: "Segmentation and limiting discovery-protocol exposure won't stop discovery outright but slows and narrows what's learned."),
        Technique("T1120", "Peripheral Device Discovery", ["TA0007"], "Adversaries may attempt to gather information about attached peripheral devices and components connected to a computer system. Peripheral devices could include auxiliary resources that support a variety of functionalities such as keyboards, printers, cameras, smart card readers, or removable storage. The information may be used to enhance their awareness of the system and network environment or may be used for further actions.", detect: "Bursts of enumeration commands (whoami, net user, ipconfig, AD queries) in a short window from one host are the giveaway.", mitigate: "Segmentation and limiting discovery-protocol exposure won't stop discovery outright but slows and narrows what's learned."),
        Technique("T1069", "Permission Groups Discovery", ["TA0007"], "Adversaries may attempt to discover group and permission settings. This information can help adversaries determine which user accounts and groups are available, the membership of users in particular groups, and which users and groups have elevated permissions.", detect: "Bursts of enumeration commands (whoami, net user, ipconfig, AD queries) in a short window from one host are the giveaway.", mitigate: "Segmentation and limiting discovery-protocol exposure won't stop discovery outright but slows and narrows what's learned."),
        Technique("T1566", "Phishing", ["TA0001"], "Adversaries may send phishing messages to gain access to victim systems. All forms of phishing are electronically delivered social engineering. Phishing can be targeted, known as spearphishing. In spearphishing, a specific individual, company, or industry will be targeted by the adversary. More generally, adversaries can conduct non-targeted phishing, such as in mass malware spam campaigns.", detect: "Watch authentication logs, email gateways and perimeter IDS/WAF for the first foothold — new source IPs, unusual logins, sandboxed attachment detonations.", mitigate: "MFA, patching internet-facing services, email filtering and least-privilege access are the highest-value controls at this stage."),
        Technique("T1598", "Phishing for Information", ["TA0043"], "Adversaries may send phishing messages to elicit sensitive information that can be used during targeting. Phishing for information is an attempt to trick targets into divulging information, frequently credentials or other actionable information. Phishing for information is different from Phishing in that the objective is gathering data from the victim rather than executing malicious code.", detect: "Largely pre-compromise and hard to see from inside your network; watch for scanning noise against your assets and monitor your own exposure in Shodan/Censys/CT logs.", mitigate: "Minimise what's publicly discoverable (banners, WHOIS, exposed services) — this stage is about reducing attack surface, not stopping the adversary directly."),
        Technique("T1647", "Plist File Modification", ["TA0112"], "Adversaries may modify property list files (plist files) to enable other malicious activity, while also potentially evading and bypassing system defenses. macOS applications use plist files, such as the info.plist file, to store properties and configuration settings that inform the operating system how to handle the application at runtime. Plist files are structured metadata in key-value pairs formatted in XML based on Apple's Core Foundation DTD. Plist files can be saved in text or binary format.", detect: "Alert on any attempt to disable, reconfigure or tamper with security tooling itself (AV/EDR stopped, logging turned off, firewall rules changed) — these are high-confidence signals on their own.", mitigate: "Tamper-protect security agents, centralise logs off-host, and treat any successful tampering attempt as an incident regardless of what else is seen."),
        Technique("T1677", "Poisoned Pipeline Execution", ["TA0002"], "Adversaries may manipulate continuous integration / continuous development (CI/CD) processes by injecting malicious code into the build process. There are several mechanisms for poisoning pipelines:", detect: "Process and command-line logging (EDR, PowerShell/Bash logging) catches most execution techniques as they run.", mitigate: "Application allowlisting and constrained scripting environments reduce what an adversary can execute even after they get in."),
        Technique("T1653", "Power Settings", ["TA0003"], "Adversaries may impair a system's ability to hibernate, reboot, or shut down in order to extend access to infected machines. When a computer enters a dormant state, some or all software and hardware may cease to operate which can disrupt malicious activity.", detect: "Monitor for new services, scheduled tasks, startup entries and account/key changes — persistence usually leaves a durable artifact.", mitigate: "Least privilege, restricting who can create services/tasks/accounts, and regular audits of autostart locations close most persistence paths."),
        Technique("T1542", "Pre-OS Boot", ["TA0003", "TA0005"], "Adversaries may abuse Pre-OS Boot mechanisms as a way to establish persistence on a system. During the booting process of a computer, firmware and various startup services are loaded before the operating system. These programs control flow of execution before the operating system takes control.", detect: "Monitor for new services, scheduled tasks, startup entries and account/key changes — persistence usually leaves a durable artifact.", mitigate: "Least privilege, restricting who can create services/tasks/accounts, and regular audits of autostart locations close most persistence paths."),
        Technique("T1690", "Prevent Command History Logging", ["TA0112"], "Adversaries may impair command history logging to hide commands they run on a compromised system. Various command interpreters keep track of the commands users type in their terminal so that users can retrace what they have done.", detect: "Alert on any attempt to disable, reconfigure or tamper with security tooling itself (AV/EDR stopped, logging turned off, firewall rules changed) — these are high-confidence signals on their own.", mitigate: "Tamper-protect security agents, centralise logs off-host, and treat any successful tampering attempt as an incident regardless of what else is seen."),
        Technique("T1057", "Process Discovery", ["TA0007"], "Adversaries may attempt to get information about running processes on a system. Information obtained could be used to gain an understanding of common software/applications running on systems within the network. Administrator or otherwise elevated access may provide better process details. Adversaries may use the information from Process Discovery during automated discovery to shape follow-on behaviors, including whether or not the adversary fully infects the target and/or attempts specific actions.", detect: "Bursts of enumeration commands (whoami, net user, ipconfig, AD queries) in a short window from one host are the giveaway.", mitigate: "Segmentation and limiting discovery-protocol exposure won't stop discovery outright but slows and narrows what's learned."),
        Technique("T1055", "Process Injection", ["TA0004", "TA0005"], "Adversaries may inject code into processes in order to evade process-based defenses as well as possibly elevate privileges. Process injection is a method of executing arbitrary code in the address space of a separate live process. Running code in the context of another process may allow access to the process's memory, system/network resources, and possibly elevated privileges. Execution via process injection may also evade detection from security products since the execution is masked under a legitimate process.", detect: "EDR telemetry around exploit attempts, sudo/UAC bypass patterns, and unexpected token/process manipulation are the main signals.", mitigate: "Patch known escalation vulnerabilities, enforce least privilege, and keep elevation mechanisms (UAC, sudoers) tightly configured."),
        Technique("T1572", "Protocol Tunneling", ["TA0011"], "Adversaries may tunnel network communications to and from a victim system within a separate protocol to avoid detection/network filtering and/or enable access to otherwise unreachable systems. Tunneling involves explicitly encapsulating a protocol within another. This behavior may conceal malicious traffic by blending in with existing traffic and/or provide an outer layer of encryption (similar to a VPN). Tunneling could also enable routing of network packets that would otherwise not reach their intended destination, such as SMB, RDP, or other traffic that would be filtered by network appliances or not routed over the Internet.", detect: "Beaconing analysis, DNS/TLS anomalies and egress monitoring catch C2 channels trying to blend into normal traffic.", mitigate: "Egress filtering, proxy inspection and blocking known C2 infrastructure are the main levers here."),
        Technique("T1090", "Proxy", ["TA0011"], "Adversaries may use a connection proxy to direct network traffic between systems or act as an intermediary for network communications to a command and control server to avoid direct connections to their infrastructure. Many tools exist that enable traffic redirection through proxies or port redirection, including HTRAN, ZXProxy, and ZXPortMap. Adversaries use these types of proxies to manage command and control communications, reduce the number of simultaneous outbound network connections, provide resiliency in the face of connection loss, or to ride over existing trusted communications paths between victims to avoid suspicion. Adversaries may chain together multiple proxies to further disguise the source of malicious traffic.", detect: "Beaconing analysis, DNS/TLS anomalies and egress monitoring catch C2 channels trying to blend into normal traffic.", mitigate: "Egress filtering, proxy inspection and blocking known C2 infrastructure are the main levers here."),
        Technique("T1682", "Query Public AI Services", ["TA0043"], "Adversaries may query publicly accessible artificial intelligence (AI) services, such as large language models (LLMs), to support targeting and operations. In addition to searching websites or databases directly (i.e., Search Open Websites/Domains), adversaries may use AI services to synthesize, aggregate, and analyze publicly available information at scale. This may include identifying individuals or organizations to target, researching organizational structures and personnel, identifying technologies used by target organizations, researching business relationships to develop plausible pretexts for Social Engineering approaches, identifying contact information for use in Phishing or Phishing for Information, or gathering derogatory or sensitive information about individuals that may be used for extortion or coercion.", detect: "Largely pre-compromise and hard to see from inside your network; watch for scanning noise against your assets and monitor your own exposure in Shodan/Censys/CT logs.", mitigate: "Minimise what's publicly discoverable (banners, WHOIS, exposed services) — this stage is about reducing attack surface, not stopping the adversary directly."),
        Technique("T1012", "Query Registry", ["TA0007"], "Adversaries may interact with the Windows Registry to gather information about the system, configuration, and installed software.", detect: "Bursts of enumeration commands (whoami, net user, ipconfig, AD queries) in a short window from one host are the giveaway.", mitigate: "Segmentation and limiting discovery-protocol exposure won't stop discovery outright but slows and narrows what's learned."),
        Technique("T1620", "Reflective Code Loading", ["TA0005"], "Adversaries may reflectively load code into a process in order to conceal the execution of malicious payloads. Reflective loading involves allocating then executing payloads directly within the memory of the process, vice creating a thread or process backed by a file path on disk (e.g., Shared Modules).", detect: "Behavioural/EDR detection and centralised logging matter here, since the goal is to blend in or hide rather than be loud.", mitigate: "Forward logs off-host, use application control, and favour behavioural over signature-based detection so evading one layer doesn't mean invisibility."),
        Technique("T1219", "Remote Access Tools", ["TA0011"], "An adversary may use legitimate remote access tools to establish an interactive command and control channel within a network. Remote access tools create a session between two trusted hosts through a graphical interface, a command line interaction, a protocol tunnel via development or management software, or hardware-level access such as KVM (Keyboard, Video, Mouse) over IP solutions. Desktop support software (usually graphical interface) and remote management software (typically command line interface) allow a user to control a computer remotely as if they are a local user inheriting the user or software permissions. This software is commonly used for troubleshooting, software installation, and system management. Adversaries may similarly abuse response features included in EDR and other defensive tools that enable remote access.", detect: "Beaconing analysis, DNS/TLS anomalies and egress monitoring catch C2 channels trying to blend into normal traffic.", mitigate: "Egress filtering, proxy inspection and blocking known C2 infrastructure are the main levers here."),
        Technique("T1563", "Remote Service Session Hijacking", ["TA0008"], "Adversaries may take control of preexisting sessions with remote services to move laterally in an environment. Users may use valid credentials to log into a service specifically designed to accept remote connections, such as telnet, SSH, and RDP. When a user logs into a service, a session will be established that will allow them to maintain a continuous interaction with that service.", detect: "New admin sessions, unusual authentication patterns between hosts, and file transfers to admin shares are the key signals.", mitigate: "MFA, network segmentation, and restricting admin protocols (RDP/SMB/WinRM) between zones limit how far a foothold can spread."),
        Technique("T1021", "Remote Services", ["TA0008"], "Adversaries may use Valid Accounts to log into a service that accepts remote connections, such as telnet, SSH, and VNC. The adversary may then perform actions as the logged-on user.", detect: "New admin sessions, unusual authentication patterns between hosts, and file transfers to admin shares are the key signals.", mitigate: "MFA, network segmentation, and restricting admin protocols (RDP/SMB/WinRM) between zones limit how far a foothold can spread."),
        Technique("T1018", "Remote System Discovery", ["TA0007"], "Adversaries may attempt to get a listing of other systems by IP address, hostname, or other logical identifier on a network that may be used for Lateral Movement from the current system. Functionality could exist within remote access tools to enable this, but utilities available on the operating system could also be used such as Ping, net view using Net, or, on ESXi servers, esxcli network diag ping.", detect: "Bursts of enumeration commands (whoami, net user, ipconfig, AD queries) in a short window from one host are the giveaway.", mitigate: "Segmentation and limiting discovery-protocol exposure won't stop discovery outright but slows and narrows what's learned."),
        Technique("T1091", "Replication Through Removable Media", ["TA0001", "TA0008"], "Adversaries may move onto systems, possibly those on disconnected or air-gapped networks, by copying malware to removable media and taking advantage of Autorun features when the media is inserted into a system and executes. In the case of Lateral Movement, this may occur through modification of executable files stored on removable media or by copying malware and renaming it to look like a legitimate file to trick users into executing it on a separate system. In the case of Initial Access, this may occur through manual manipulation of the media, modification of systems used to initially format the media, or modification to the media's firmware itself.", detect: "Watch authentication logs, email gateways and perimeter IDS/WAF for the first foothold — new source IPs, unusual logins, sandboxed attachment detonations.", mitigate: "MFA, patching internet-facing services, email filtering and least-privilege access are the highest-value controls at this stage."),
        Technique("T1496", "Resource Hijacking", ["TA0040"], "Adversaries may leverage the resources of co-opted systems to complete resource-intensive tasks, which may impact system and/or hosted service availability.", detect: "Mass file writes/deletes/renames, shadow-copy deletion, and unexpected shutdown/reboot events are late-stage, high-confidence signals.", mitigate: "Offline backups, least privilege and EDR are the last line of defence once an adversary reaches this stage."),
        Technique("T1207", "Rogue Domain Controller", ["TA0112"], "Adversaries may register a rogue Domain Controller to enable manipulation of Active Directory data. DCShadow may be used to create a rogue Domain Controller (DC). DCShadow is a method of manipulating Active Directory (AD) data, including objects and schemas, by registering (or reusing an inactive registration) and simulating the behavior of a DC. Once registered, a rogue DC may be able to inject and replicate changes into AD infrastructure for any domain object, including credentials and keys.", detect: "Alert on any attempt to disable, reconfigure or tamper with security tooling itself (AV/EDR stopped, logging turned off, firewall rules changed) — these are high-confidence signals on their own.", mitigate: "Tamper-protect security agents, centralise logs off-host, and treat any successful tampering attempt as an incident regardless of what else is seen."),
        Technique("T1014", "Rootkit", ["TA0005"], "Adversaries may use rootkits to hide the presence of programs, files, network connections, services, drivers, and other system components. Rootkits are programs that hide the existence of malware by intercepting/hooking and modifying operating system API calls that supply system information.", detect: "Behavioural/EDR detection and centralised logging matter here, since the goal is to blend in or hide rather than be loud.", mitigate: "Forward logs off-host, use application control, and favour behavioural over signature-based detection so evading one layer doesn't mean invisibility."),
        Technique("T1688", "Safe Mode Boot", ["TA0112"], "Adversaries may abuse Windows safe mode to disable endpoint defenses. Safe mode starts up the Windows operating system with a limited set of drivers and services. Third-party security software such as endpoint detection and response (EDR) tools may not start after booting Windows in safe mode. There are two versions of safe mode: Safe Mode and Safe Mode with Networking. It is possible to start additional services after a safe mode boot.", detect: "Alert on any attempt to disable, reconfigure or tamper with security tooling itself (AV/EDR stopped, logging turned off, firewall rules changed) — these are high-confidence signals on their own.", mitigate: "Tamper-protect security agents, centralise logs off-host, and treat any successful tampering attempt as an incident regardless of what else is seen."),
        Technique("T1053", "Scheduled Task/Job", ["TA0002", "TA0003", "TA0004"], "Adversaries may abuse task scheduling functionality to facilitate initial or recurring execution of malicious code. Utilities exist within all major operating systems to schedule programs or scripts to be executed at a specified date and time. A task can also be scheduled on a remote system, provided the proper authentication is met (ex: RPC and file and printer sharing in Windows environments). Scheduling a task on a remote system typically may require being a member of an admin or otherwise privileged group on the remote system.", detect: "Process and command-line logging (EDR, PowerShell/Bash logging) catches most execution techniques as they run.", mitigate: "Application allowlisting and constrained scripting environments reduce what an adversary can execute even after they get in."),
        Technique("T1029", "Scheduled Transfer", ["TA0010"], "Adversaries may schedule data exfiltration to be performed only at certain times of day or at certain intervals. This could be done to blend traffic patterns with normal activity or availability.", detect: "Outbound volume anomalies and uploads to unsanctioned cloud/web services are the main signal.", mitigate: "DLP, egress limits and blocking/allowlisting web services reduce how data can leave undetected."),
        Technique("T1113", "Screen Capture", ["TA0009"], "Adversaries may attempt to take screen captures of the desktop to gather information over the course of an operation. Screen capturing functionality may be included as a feature of a remote access tool used in post-compromise operations. Taking a screenshot is also typically possible through native utilities or API calls, such as CopyFromScreen, xwd, or screencapture.", detect: "Mass file access, staging directories, and bulk reads across many hosts are typical before data is moved out.", mitigate: "DLP, least privilege and encryption at rest limit what's useful to an adversary even if collection succeeds."),
        Technique("T1597", "Search Closed Sources", ["TA0043"], "Adversaries may search and gather information about victims from closed (e.g., paid, private, or otherwise not freely available) sources that can be used during targeting. Information about victims may be available for purchase from reputable private sources and databases, such as paid subscriptions to feeds of technical/threat intelligence data. Adversaries may also purchase information from less-reputable sources such as dark web or cybercrime blackmarkets.", detect: "Largely pre-compromise and hard to see from inside your network; watch for scanning noise against your assets and monitor your own exposure in Shodan/Censys/CT logs.", mitigate: "Minimise what's publicly discoverable (banners, WHOIS, exposed services) — this stage is about reducing attack surface, not stopping the adversary directly."),
        Technique("T1596", "Search Open Technical Databases", ["TA0043"], "Adversaries may search freely available technical databases for information about victims that can be used during targeting. Information about victims may be available in online databases and repositories, such as registrations of domains/certificates as well as public collections of network data/artifacts gathered from traffic and/or scans.", detect: "Largely pre-compromise and hard to see from inside your network; watch for scanning noise against your assets and monitor your own exposure in Shodan/Censys/CT logs.", mitigate: "Minimise what's publicly discoverable (banners, WHOIS, exposed services) — this stage is about reducing attack surface, not stopping the adversary directly."),
        Technique("T1593", "Search Open Websites/Domains", ["TA0043"], "Adversaries may search freely available websites and/or domains for information about victims that can be used during targeting. Information about victims may be available in various online sites, such as social media, new sites, or those hosting information about business operations such as hiring or requested/rewarded contracts.", detect: "Largely pre-compromise and hard to see from inside your network; watch for scanning noise against your assets and monitor your own exposure in Shodan/Censys/CT logs.", mitigate: "Minimise what's publicly discoverable (banners, WHOIS, exposed services) — this stage is about reducing attack surface, not stopping the adversary directly."),
        Technique("T1681", "Search Threat Vendor Data", ["TA0043"], "Threat actors may seek information/indicators from closed or open threat intelligence sources gathered about their own campaigns, as well as those conducted by other adversaries that may align with their target industries, capabilities/objectives, or other operational concerns. These reports may include descriptions of behavior, detailed breakdowns of attacks, atomic indicators such as malware hashes or IP addresses, timelines of a group’s activity, and more. Adversaries may change their behavior when planning their future operations.", detect: "Largely pre-compromise and hard to see from inside your network; watch for scanning noise against your assets and monitor your own exposure in Shodan/Censys/CT logs.", mitigate: "Minimise what's publicly discoverable (banners, WHOIS, exposed services) — this stage is about reducing attack surface, not stopping the adversary directly."),
        Technique("T1594", "Search Victim-Owned Websites", ["TA0043"], "Adversaries may search websites owned by the victim for information that can be used during targeting. Victim-owned websites may contain a variety of details, including names of departments/divisions, physical locations, and data about key employees such as names, roles, and contact info (ex: Email Addresses). These sites may also have details highlighting business operations and relationships.", detect: "Largely pre-compromise and hard to see from inside your network; watch for scanning noise against your assets and monitor your own exposure in Shodan/Censys/CT logs.", mitigate: "Minimise what's publicly discoverable (banners, WHOIS, exposed services) — this stage is about reducing attack surface, not stopping the adversary directly."),
        Technique("T1679", "Selective Exclusion", ["TA0005"], "Adversaries may intentionally exclude certain files, folders, directories, file types, or system components from encryption or tampering during a ransomware or malicious payload execution. Some file extensions that adversaries may avoid encrypting include .dll, .exe, and .lnk.", detect: "Behavioural/EDR detection and centralised logging matter here, since the goal is to blend in or hide rather than be loud.", mitigate: "Forward logs off-host, use application control, and favour behavioural over signature-based detection so evading one layer doesn't mean invisibility."),
        Technique("T1505", "Server Software Component", ["TA0003"], "Adversaries may abuse legitimate extensible development features of servers to establish persistent access to systems. Enterprise server applications may include features that allow developers to write and install software or scripts to extend the functionality of the main application. Adversaries may install malicious components to extend and abuse server applications.", detect: "Monitor for new services, scheduled tasks, startup entries and account/key changes — persistence usually leaves a durable artifact.", mitigate: "Least privilege, restricting who can create services/tasks/accounts, and regular audits of autostart locations close most persistence paths."),
        Technique("T1648", "Serverless Execution", ["TA0002"], "Adversaries may abuse serverless computing, integration, and automation services to execute arbitrary code in cloud environments. Many cloud providers offer a variety of serverless resources, including compute engines, application integration services, and web servers.", detect: "Process and command-line logging (EDR, PowerShell/Bash logging) catches most execution techniques as they run.", mitigate: "Application allowlisting and constrained scripting environments reduce what an adversary can execute even after they get in."),
        Technique("T1489", "Service Stop", ["TA0040"], "Adversaries may stop or disable services on a system to render those services unavailable to legitimate users. Stopping critical services or processes can inhibit or stop response to an incident or aid in the adversary's overall objectives to cause damage to the environment.", detect: "Mass file writes/deletes/renames, shadow-copy deletion, and unexpected shutdown/reboot events are late-stage, high-confidence signals.", mitigate: "Offline backups, least privilege and EDR are the last line of defence once an adversary reaches this stage."),
        Technique("T1129", "Shared Modules", ["TA0002"], "Adversaries may execute malicious payloads via loading shared modules. Shared modules are executable files that are loaded into processes to provide access to reusable code, such as specific custom functions or invoking OS API functions (i.e., Native API).", detect: "Process and command-line logging (EDR, PowerShell/Bash logging) catches most execution techniques as they run.", mitigate: "Application allowlisting and constrained scripting environments reduce what an adversary can execute even after they get in."),
        Technique("T1684", "Social Engineering", ["TA0005"], "Adversaries may use social engineering techniques to influence users to take actions that result in unauthorized access, approval of changes, disclosure of sensitive information, or execution of adversary-supplied instructions (i.e., introduction of malicious payloads or software), while minimizing technical indicators.", detect: "Behavioural/EDR detection and centralised logging matter here, since the goal is to blend in or hide rather than be loud.", mitigate: "Forward logs off-host, use application control, and favour behavioural over signature-based detection so evading one layer doesn't mean invisibility."),
        Technique("T1072", "Software Deployment Tools", ["TA0002", "TA0008"], "Adversaries may gain access to and use centralized software suites installed within an enterprise to execute commands and move laterally through the network. Configuration management and software deployment applications may be used in an enterprise network or cloud environment for routine administration purposes. These systems may also be integrated into CI/CD pipelines. Examples of such solutions include: SCCM, HBSS, Altiris, AWS Systems Manager, Microsoft Intune, Azure Arc, and GCP Deployment Manager.", detect: "Process and command-line logging (EDR, PowerShell/Bash logging) catches most execution techniques as they run.", mitigate: "Application allowlisting and constrained scripting environments reduce what an adversary can execute even after they get in."),
        Technique("T1518", "Software Discovery", ["TA0007"], "Adversaries may attempt to get a listing of software and software versions that are installed on a system or in a cloud environment. Adversaries may use the information from Software Discovery during automated discovery to shape follow-on behaviors, including whether or not the adversary fully infects the target and/or attempts specific actions.", detect: "Bursts of enumeration commands (whoami, net user, ipconfig, AD queries) in a short window from one host are the giveaway.", mitigate: "Segmentation and limiting discovery-protocol exposure won't stop discovery outright but slows and narrows what's learned."),
        Technique("T1176", "Software Extensions", ["TA0003"], "Adversaries may abuse software extensions to establish persistent access to victim systems. Software extensions are modular components that enhance or customize the functionality of software applications, including web browsers, Integrated Development Environments (IDEs), and other platforms. Extensions are typically installed via official marketplaces, app stores, or manually loaded by users, and they often inherit the permissions and access levels of the host application.", detect: "Monitor for new services, scheduled tasks, startup entries and account/key changes — persistence usually leaves a durable artifact.", mitigate: "Least privilege, restricting who can create services/tasks/accounts, and regular audits of autostart locations close most persistence paths."),
        Technique("T1608", "Stage Capabilities", ["TA0042"], "Adversaries may upload, install, or otherwise set up capabilities that can be used during targeting. To support their operations, an adversary may need to take capabilities they developed (Develop Capabilities) or obtained (Obtain Capabilities) and stage them on infrastructure under their control. These capabilities may be staged on infrastructure that was previously purchased/rented by the adversary (Acquire Infrastructure) or was otherwise compromised by them (Compromise Infrastructure). Capabilities may also be staged on web services, such as GitHub or Pastebin, or on Platform-as-a-Service (PaaS) offerings that enable users to easily provision applications.", detect: "Happens on adversary-controlled infrastructure, so it's invisible to your monitoring; rely on threat-intel feeds for newly-registered domains/certificates tied to known campaigns.", mitigate: "Block or flag indicators from threat-intel feeds (new domains, abused certificates) before they're used against you."),
        Technique("T1528", "Steal Application Access Token", ["TA0006"], "Adversaries can steal application access tokens as a means of acquiring credentials to access remote systems and resources.", detect: "Failed-login spikes, LSASS/SAM/shadow access, and access to credential stores (browsers, password managers) are the classic signals.", mitigate: "MFA, credential-guard/LAPS-style protections, secret scanning and rotating any exposed credential are the highest-value controls."),
        Technique("T1697", "Steal Application Specific Passwords", ["TA0006"], "Adversaries may steal Application Specific Passwords (ASPs) to gain access to Valid Accounts, bypassing multifactor authentication (MFA) methods. ASPs are passwords typically used to give third-party applications or legacy devices (which do not support MFA methods) account access.", detect: "Failed-login spikes, LSASS/SAM/shadow access, and access to credential stores (browsers, password managers) are the classic signals.", mitigate: "MFA, credential-guard/LAPS-style protections, secret scanning and rotating any exposed credential are the highest-value controls."),
        Technique("T1649", "Steal or Forge Authentication Certificates", ["TA0006"], "Adversaries may steal or forge certificates used for authentication to access remote systems or resources. Digital certificates are often used to sign and encrypt messages and/or files. Certificates are also used as authentication material. For example, Entra ID device certificates and Active Directory Certificate Services (AD CS) certificates bind to an identity and can be used as credentials for domain accounts.", detect: "Failed-login spikes, LSASS/SAM/shadow access, and access to credential stores (browsers, password managers) are the classic signals.", mitigate: "MFA, credential-guard/LAPS-style protections, secret scanning and rotating any exposed credential are the highest-value controls."),
        Technique("T1558", "Steal or Forge Kerberos Tickets", ["TA0006"], "Adversaries may attempt to subvert Kerberos authentication by stealing or forging Kerberos tickets to enable Pass the Ticket. Kerberos is an authentication protocol widely used in modern Windows domain environments. In Kerberos environments, referred to as \"realms\", there are three basic participants: client, service, and Key Distribution Center (KDC). Clients request access to a service and through the exchange of Kerberos tickets, originating from KDC, they are granted access after having successfully authenticated. The KDC is responsible for both authentication and ticket granting. Adversaries may attempt to abuse Kerberos by stealing tickets or forging tickets to enable unauthorized access.", detect: "Failed-login spikes, LSASS/SAM/shadow access, and access to credential stores (browsers, password managers) are the classic signals.", mitigate: "MFA, credential-guard/LAPS-style protections, secret scanning and rotating any exposed credential are the highest-value controls."),
        Technique("T1539", "Steal Web Session Cookie", ["TA0006"], "An adversary may steal web application or service session cookies and use them to gain access to web applications or Internet services as an authenticated user without needing credentials. Web applications and services often use session cookies as an authentication token after a user has authenticated to a website.", detect: "Failed-login spikes, LSASS/SAM/shadow access, and access to credential stores (browsers, password managers) are the classic signals.", mitigate: "MFA, credential-guard/LAPS-style protections, secret scanning and rotating any exposed credential are the highest-value controls."),
        Technique("T1553", "Subvert Trust Controls", ["TA0112"], "Adversaries may undermine security controls that will either warn users of untrusted activity or prevent execution of untrusted programs. Operating systems and security products may contain mechanisms to identify programs or websites as possessing some level of trust. Examples of such features would include a program being allowed to run because it is signed by a valid code signing certificate, a program prompting the user with a warning because it has an attribute set from being downloaded from the Internet, or getting an indication that you are about to connect to an untrusted site.", detect: "Alert on any attempt to disable, reconfigure or tamper with security tooling itself (AV/EDR stopped, logging turned off, firewall rules changed) — these are high-confidence signals on their own.", mitigate: "Tamper-protect security agents, centralise logs off-host, and treat any successful tampering attempt as an incident regardless of what else is seen."),
        Technique("T1195", "Supply Chain Compromise", ["TA0001"], "Adversaries may manipulate products or product delivery mechanisms prior to receipt by a final consumer for the purpose of data or system compromise.", detect: "Watch authentication logs, email gateways and perimeter IDS/WAF for the first foothold — new source IPs, unusual logins, sandboxed attachment detonations.", mitigate: "MFA, patching internet-facing services, email filtering and least-privilege access are the highest-value controls at this stage."),
        Technique("T1218", "System Binary Proxy Execution", ["TA0005"], "Adversaries may bypass process and/or signature-based defenses by proxying execution of malicious content with signed, or otherwise trusted, binaries. Binaries used in this technique are often Microsoft-signed files, indicating that they have been either downloaded from Microsoft or are already native in the operating system. Binaries signed with trusted digital certificates can typically execute on Windows systems protected by digital signature validation. Several Microsoft signed binaries that are default on Windows installations can be used to proxy execution of other files or commands.", detect: "Behavioural/EDR detection and centralised logging matter here, since the goal is to blend in or hide rather than be loud.", mitigate: "Forward logs off-host, use application control, and favour behavioural over signature-based detection so evading one layer doesn't mean invisibility."),
        Technique("T1082", "System Information Discovery", ["TA0007"], "An adversary may attempt to get detailed information about the operating system and hardware, including version, patches, hotfixes, service packs, and architecture. Adversaries may use this information to shape follow-on behaviors, including whether or not the adversary fully infects the target and/or attempts specific actions. This behavior is distinct from Local Storage Discovery which is an adversary's discovery of local drive, disks and/or volumes.", detect: "Bursts of enumeration commands (whoami, net user, ipconfig, AD queries) in a short window from one host are the giveaway.", mitigate: "Segmentation and limiting discovery-protocol exposure won't stop discovery outright but slows and narrows what's learned."),
        Technique("T1614", "System Location Discovery", ["TA0007"], "Adversaries may gather information in an attempt to calculate the geographical location of a victim host. Adversaries may use the information from System Location Discovery during automated discovery to shape follow-on behaviors, including whether or not the adversary fully infects the target and/or attempts specific actions.", detect: "Bursts of enumeration commands (whoami, net user, ipconfig, AD queries) in a short window from one host are the giveaway.", mitigate: "Segmentation and limiting discovery-protocol exposure won't stop discovery outright but slows and narrows what's learned."),
        Technique("T1016", "System Network Configuration Discovery", ["TA0007"], "Adversaries may look for details about the network configuration and settings, such as IP and/or MAC addresses, of systems they access or through information discovery of remote systems. Several operating system administration utilities exist that can be used to gather this information. Examples include Arp, ipconfig/ifconfig, nbtstat, and route.", detect: "Bursts of enumeration commands (whoami, net user, ipconfig, AD queries) in a short window from one host are the giveaway.", mitigate: "Segmentation and limiting discovery-protocol exposure won't stop discovery outright but slows and narrows what's learned."),
        Technique("T1049", "System Network Connections Discovery", ["TA0007"], "Adversaries may attempt to get a listing of network connections to or from the compromised system they are currently accessing or from remote systems by querying for information over the network.", detect: "Bursts of enumeration commands (whoami, net user, ipconfig, AD queries) in a short window from one host are the giveaway.", mitigate: "Segmentation and limiting discovery-protocol exposure won't stop discovery outright but slows and narrows what's learned."),
        Technique("T1033", "System Owner/User Discovery", ["TA0007"], "Adversaries may attempt to identify the primary user, currently logged in user, set of users that commonly uses a system, or whether a user is actively using the system. They may do this, for example, by retrieving account usernames or by using OS Credential Dumping. The information may be collected in a number of different ways using other Discovery techniques, because user and username details are prevalent throughout a system and include running process ownership, file/directory ownership, session information, and system logs. Adversaries may use the information from System Owner/User Discovery during automated discovery to shape follow-on behaviors, including whether or not the adversary fully infects the target and/or attempts specific actions.", detect: "Bursts of enumeration commands (whoami, net user, ipconfig, AD queries) in a short window from one host are the giveaway.", mitigate: "Segmentation and limiting discovery-protocol exposure won't stop discovery outright but slows and narrows what's learned."),
        Technique("T1216", "System Script Proxy Execution", ["TA0005"], "Adversaries may use trusted scripts, often signed with certificates, to proxy the execution of malicious files. Several Microsoft signed scripts that have been downloaded from Microsoft or are default on Windows installations can be used to proxy execution of other files. This behavior may be abused by adversaries to execute malicious files that could bypass application control and signature validation on systems.", detect: "Behavioural/EDR detection and centralised logging matter here, since the goal is to blend in or hide rather than be loud.", mitigate: "Forward logs off-host, use application control, and favour behavioural over signature-based detection so evading one layer doesn't mean invisibility."),
        Technique("T1007", "System Service Discovery", ["TA0007"], "Adversaries may try to gather information about registered local system services. Adversaries may obtain information about services using tools as well as OS utility commands such as sc query, tasklist /svc, systemctl --type=service, and net start. Adversaries may also gather information about schedule tasks via commands such as schtasks on Windows or crontab -l on Linux and macOS.", detect: "Bursts of enumeration commands (whoami, net user, ipconfig, AD queries) in a short window from one host are the giveaway.", mitigate: "Segmentation and limiting discovery-protocol exposure won't stop discovery outright but slows and narrows what's learned."),
        Technique("T1569", "System Services", ["TA0002"], "Adversaries may abuse system services or daemons to execute commands or programs. Adversaries can execute malicious content by interacting with or creating services either locally or remotely. Many services are set to run at boot, which can aid in achieving persistence (Create or Modify System Process), but adversaries can also abuse services for one-time or temporary execution.", detect: "Process and command-line logging (EDR, PowerShell/Bash logging) catches most execution techniques as they run.", mitigate: "Application allowlisting and constrained scripting environments reduce what an adversary can execute even after they get in."),
        Technique("T1529", "System Shutdown/Reboot", ["TA0040"], "Adversaries may shutdown/reboot systems to interrupt access to, or aid in the destruction of, those systems. Operating systems may contain commands to initiate a shutdown/reboot of a machine or network device. In some cases, these commands may also be used to initiate a shutdown/reboot of a remote computer or network device via Network Device CLI (e.g. reload). They may also include shutdown/reboot of a virtual machine via hypervisor / cloud consoles or command line tools.", detect: "Mass file writes/deletes/renames, shadow-copy deletion, and unexpected shutdown/reboot events are late-stage, high-confidence signals.", mitigate: "Offline backups, least privilege and EDR are the last line of defence once an adversary reaches this stage."),
        Technique("T1124", "System Time Discovery", ["TA0007"], "An adversary may gather the system time and/or time zone settings from a local or remote system. The system time is set and stored by services, such as the Windows Time Service on Windows or systemsetup on macOS. These time settings may also be synchronized between systems and services in an enterprise network, typically accomplished with a network time server within a domain.", detect: "Bursts of enumeration commands (whoami, net user, ipconfig, AD queries) in a short window from one host are the giveaway.", mitigate: "Segmentation and limiting discovery-protocol exposure won't stop discovery outright but slows and narrows what's learned."),
        Technique("T1080", "Taint Shared Content", ["TA0008"], "Adversaries may deliver payloads to remote systems by adding content to shared storage locations, such as network drives or internal code repositories. Content stored on network drives or in other shared locations may be tainted by adding malicious programs, scripts, or exploit code to otherwise valid files. Once a user opens the shared tainted content, the malicious portion can be executed to run the adversary's code on a remote system. Adversaries may use tainted shared content to move laterally.", detect: "New admin sessions, unusual authentication patterns between hosts, and file transfers to admin shares are the key signals.", mitigate: "MFA, network segmentation, and restricting admin protocols (RDP/SMB/WinRM) between zones limit how far a foothold can spread."),
        Technique("T1221", "Template Injection", ["TA0005"], "Adversaries may create or modify references in user document templates to conceal malicious code or force authentication attempts. For example, Microsoft’s Office Open XML (OOXML) specification defines an XML-based format for Office documents (.docx, xlsx, .pptx) to replace older binary formats (.doc, .xls, .ppt). OOXML files are packed together ZIP archives compromised of various XML files, referred to as parts, containing properties that collectively define how a document is rendered.", detect: "Behavioural/EDR detection and centralised logging matter here, since the goal is to blend in or hide rather than be loud.", mitigate: "Forward logs off-host, use application control, and favour behavioural over signature-based detection so evading one layer doesn't mean invisibility."),
        Technique("T1205", "Traffic Signaling", ["TA0003", "TA0005", "TA0011"], "Adversaries may use traffic signaling to hide open ports or other malicious functionality used for persistence or command and control. Traffic signaling involves the use of a magic value or sequence that must be sent to a system to trigger a special response, such as opening a closed port or executing a malicious task. This may take the form of sending a series of packets with certain characteristics before a port will be opened that the adversary can use for command and control. Usually this series of packets consists of attempted connections to a predefined sequence of closed ports (i.e. Port Knocking), but can involve unusual flags, specific strings, or other unique characteristics. After the sequence is completed, opening a port may be accomplished by the host-based firewall, but could also be implemented by custom software.", detect: "Monitor for new services, scheduled tasks, startup entries and account/key changes — persistence usually leaves a durable artifact.", mitigate: "Least privilege, restricting who can create services/tasks/accounts, and regular audits of autostart locations close most persistence paths."),
        Technique("T1537", "Transfer Data to Cloud Account", ["TA0010"], "Adversaries may exfiltrate data by transferring the data, including through sharing/syncing and creating backups of cloud environments, to another cloud account they control on the same service.", detect: "Outbound volume anomalies and uploads to unsanctioned cloud/web services are the main signal.", mitigate: "DLP, egress limits and blocking/allowlisting web services reduce how data can leave undetected."),
        Technique("T1127", "Trusted Developer Utilities Proxy Execution", ["TA0002", "TA0005"], "Adversaries may take advantage of trusted developer utilities to proxy execution of malicious payloads. There are many utilities used for software development related tasks that can be used to execute code in various forms to assist in development, debugging, and reverse engineering. These utilities may often be signed with legitimate certificates that allow them to execute on a system and proxy execution of malicious code through a trusted process that effectively bypasses application control solutions.", detect: "Process and command-line logging (EDR, PowerShell/Bash logging) catches most execution techniques as they run.", mitigate: "Application allowlisting and constrained scripting environments reduce what an adversary can execute even after they get in."),
        Technique("T1199", "Trusted Relationship", ["TA0001"], "Adversaries may breach or otherwise leverage organizations who have access to intended victims. Access through trusted third party relationship abuses an existing connection that may not be protected or receives less scrutiny than standard mechanisms of gaining access to a network.", detect: "Watch authentication logs, email gateways and perimeter IDS/WAF for the first foothold — new source IPs, unusual logins, sandboxed attachment detonations.", mitigate: "MFA, patching internet-facing services, email filtering and least-privilege access are the highest-value controls at this stage."),
        Technique("T1552", "Unsecured Credentials", ["TA0006"], "Adversaries may search compromised systems to find and obtain insecurely stored credentials. These credentials can be stored and/or misplaced in many locations on a system, including plaintext files (e.g. Shell History), operating system or application-specific repositories (e.g. Credentials in Registry), or other specialized files/artifacts (e.g. Private Keys).", detect: "Failed-login spikes, LSASS/SAM/shadow access, and access to credential stores (browsers, password managers) are the classic signals.", mitigate: "MFA, credential-guard/LAPS-style protections, secret scanning and rotating any exposed credential are the highest-value controls."),
        Technique("T1535", "Unused/Unsupported Cloud Regions", ["TA0005"], "Adversaries may create cloud instances in unused geographic service regions in order to evade detection. Access is usually obtained through compromising accounts used to manage cloud infrastructure.", detect: "Behavioural/EDR detection and centralised logging matter here, since the goal is to blend in or hide rather than be loud.", mitigate: "Forward logs off-host, use application control, and favour behavioural over signature-based detection so evading one layer doesn't mean invisibility."),
        Technique("T1550", "Use Alternate Authentication Material", ["TA0008"], "Adversaries may use alternate authentication material, such as password hashes, Kerberos tickets, and application access tokens, in order to move laterally within an environment and bypass normal system access controls.", detect: "New admin sessions, unusual authentication patterns between hosts, and file transfers to admin shares are the key signals.", mitigate: "MFA, network segmentation, and restricting admin protocols (RDP/SMB/WinRM) between zones limit how far a foothold can spread."),
        Technique("T1204", "User Execution", ["TA0002"], "An adversary may rely upon specific actions by a user in order to gain execution. Users may be subjected to social engineering to get them to execute malicious code by, for example, opening a malicious document file or link. These user actions will typically be observed as follow-on behavior from forms of Phishing.", detect: "Process and command-line logging (EDR, PowerShell/Bash logging) catches most execution techniques as they run.", mitigate: "Application allowlisting and constrained scripting environments reduce what an adversary can execute even after they get in."),
        Technique("T1078", "Valid Accounts", ["TA0001", "TA0003", "TA0004", "TA0005"], "Adversaries may obtain and abuse credentials of existing accounts as a means of gaining Initial Access, Persistence, Privilege Escalation, or Defense Evasion. Compromised credentials may be used to bypass access controls placed on various resources on systems within the network and may even be used for persistent access to remote systems and externally available services, such as VPNs, Outlook Web Access, network devices, and remote desktop. Compromised credentials may also grant an adversary increased privilege to specific systems or access to restricted areas of the network. Adversaries may choose not to use malware or tools in conjunction with the legitimate access those credentials provide to make it harder to detect their presence.", detect: "Watch authentication logs, email gateways and perimeter IDS/WAF for the first foothold — new source IPs, unusual logins, sandboxed attachment detonations.", mitigate: "MFA, patching internet-facing services, email filtering and least-privilege access are the highest-value controls at this stage."),
        Technique("T1125", "Video Capture", ["TA0009"], "An adversary can leverage a computer's peripheral devices (e.g., integrated cameras or webcams) or applications (e.g., video call services) to capture video recordings for the purpose of gathering information. Images may also be captured from devices or applications, potentially in specified intervals, in lieu of video files.", detect: "Mass file access, staging directories, and bulk reads across many hosts are typical before data is moved out.", mitigate: "DLP, least privilege and encryption at rest limit what's useful to an adversary even if collection succeeds."),
        Technique("T1673", "Virtual Machine Discovery", ["TA0007"], "An adversary may attempt to enumerate running virtual machines (VMs) after gaining access to a host or hypervisor. For example, adversaries may enumerate a list of VMs on an ESXi hypervisor using a Hypervisor CLI such as esxcli or vim-cmd (e.g. esxcli vm process list or vim-cmd vmsvc/getallvms). Adversaries may also directly leverage a graphical user interface, such as VMware vCenter, in order to view virtual machines on a host.", detect: "Bursts of enumeration commands (whoami, net user, ipconfig, AD queries) in a short window from one host are the giveaway.", mitigate: "Segmentation and limiting discovery-protocol exposure won't stop discovery outright but slows and narrows what's learned."),
        Technique("T1497", "Virtualization/Sandbox Evasion", ["TA0005", "TA0007"], "Adversaries may employ various means to detect and avoid virtualization and analysis environments. This may include changing behaviors based on the results of checks for the presence of artifacts indicative of a virtual machine environment (VME) or sandbox. If the adversary detects a VME, they may alter their malware to disengage from the victim or conceal the core functions of the implant. They may also search for VME artifacts before dropping secondary or additional payloads. Adversaries may use the information learned from Virtualization/Sandbox Evasion during automated discovery to shape follow-on behaviors.", detect: "Behavioural/EDR detection and centralised logging matter here, since the goal is to blend in or hide rather than be loud.", mitigate: "Forward logs off-host, use application control, and favour behavioural over signature-based detection so evading one layer doesn't mean invisibility."),
        Technique("T1600", "Weaken Encryption", ["TA0112"], "Adversaries may compromise a network device’s encryption capability in order to bypass encryption that would otherwise protect data communications.", detect: "Alert on any attempt to disable, reconfigure or tamper with security tooling itself (AV/EDR stopped, logging turned off, firewall rules changed) — these are high-confidence signals on their own.", mitigate: "Tamper-protect security agents, centralise logs off-host, and treat any successful tampering attempt as an incident regardless of what else is seen."),
        Technique("T1102", "Web Service", ["TA0011"], "Adversaries may use an existing, legitimate external Web service as a means for relaying data to/from a compromised system. Popular websites, cloud services, and social media acting as a mechanism for C2 may give a significant amount of cover due to the likelihood that hosts within a network are already communicating with them prior to a compromise. Using common services, such as those offered by Google, Microsoft, or Twitter, makes it easier for adversaries to hide in expected noise. Web service providers commonly use SSL/TLS encryption, giving adversaries an added level of protection.", detect: "Beaconing analysis, DNS/TLS anomalies and egress monitoring catch C2 channels trying to blend into normal traffic.", mitigate: "Egress filtering, proxy inspection and blocking known C2 infrastructure are the main levers here."),
        Technique("T1669", "Wi-Fi Networks", ["TA0001"], "Adversaries may gain initial access to target systems by connecting to wireless networks. They may accomplish this by exploiting open Wi-Fi networks used by target devices or by accessing secured Wi-Fi networks — requiring Valid Accounts — belonging to a target organization. Establishing a connection to a Wi-Fi access point requires a certain level of proximity to both discover and maintain a stable network connection.", detect: "Watch authentication logs, email gateways and perimeter IDS/WAF for the first foothold — new source IPs, unusual logins, sandboxed attachment detonations.", mitigate: "MFA, patching internet-facing services, email filtering and least-privilege access are the highest-value controls at this stage."),
        Technique("T1047", "Windows Management Instrumentation", ["TA0002"], "Adversaries may abuse Windows Management Instrumentation (WMI) to execute malicious commands and payloads. WMI is designed for programmers and is the infrastructure for management data and operations on Windows systems. WMI is an administration feature that provides a uniform environment to access Windows system components.", detect: "Process and command-line logging (EDR, PowerShell/Bash logging) catches most execution techniques as they run.", mitigate: "Application allowlisting and constrained scripting environments reduce what an adversary can execute even after they get in."),
        Technique("T1220", "XSL Script Processing", ["TA0005"], "Adversaries may bypass application control and obscure execution of code by embedding scripts inside XSL files. Extensible Stylesheet Language (XSL) files are commonly used to describe the processing and rendering of data within XML files. To support complex operations, the XSL standard includes support for embedded scripting in various languages.", detect: "Behavioural/EDR detection and centralised logging matter here, since the goal is to blend in or hide rather than be loud.", mitigate: "Forward logs off-host, use application control, and favour behavioural over signature-based detection so evading one layer doesn't mean invisibility."),
    ]

    public static func tactic(_ id: String) -> Tactic? { tactics.first { $0.id.caseInsensitiveCompare(id) == .orderedSame } }
    public static func technique(_ id: String) -> Technique? { techniques.first { $0.id.caseInsensitiveCompare(id) == .orderedSame } }
    public static func techniques(in tacticID: String) -> [Technique] {
        techniques.filter { t in t.tactics.contains { $0.caseInsensitiveCompare(tacticID) == .orderedSame } }
    }

    public static func search(_ query: String) -> [Technique] {
        let q = query.lowercased()
        return techniques.filter { $0.name.lowercased().contains(q) || $0.summary.lowercased().contains(q)
            || $0.detection.lowercased().contains(q) || $0.mitigation.lowercased().contains(q) || $0.id.lowercased().contains(q) }
    }

    public static func run(_ input: String) -> ToolOutput {
        let q = input.trimmed()
        // Technique id → detail
        if let t = technique(q) { return detail(t) }
        // Tactic id → techniques in it
        if let ta = tactic(q) {
            var s = ReportSection("\(ta.id) — \(ta.name)", note: ta.summary)
            for t in techniques(in: ta.id) { s.add(t.id, t.name) }
            return ToolOutput(sections: [s])
        }
        // Keyword search
        if !q.isEmpty {
            let hits = search(q)
            if hits.isEmpty {
                return ToolOutput(sections: [ReportSection("ATT&CK", items: [ReportItem("No match", "try a tactic (TA0002), a technique (T1059) or a keyword (phishing, brute, exfil)", .low)])])
            }
            var out = ToolOutput()
            var s = ReportSection("Matches for \u{201c}\(q)\u{201d} (\(hits.count))")
            for t in hits.prefix(60) { s.add(t.id, "\(t.name) — \(t.tactics.compactMap { tactic($0)?.name }.joined(separator: ", "))") }
            out.sections.append(s)
            return out
        }
        // Empty → the matrix overview
        var out = ToolOutput()
        var s = ReportSection("MITRE ATT&CK — Enterprise tactics", note: "Enter a tactic id (TA0001), technique id (T1059) or keyword. \(techniques.count) techniques covered.")
        for ta in tactics { s.add("\(ta.id) · \(ta.name)", "\(techniques(in: ta.id).count) techniques") }
        out.sections.append(s)
        return out
    }

    static func detail(_ t: Technique) -> ToolOutput {
        let tacticNames = t.tactics.compactMap { tactic($0)?.name }.joined(separator: ", ")
        var s = ReportSection("\(t.id) — \(t.name)", note: "Tactic: \(tacticNames)")
        s.add("What", t.summary)
        s.add("Detect", t.detection, .low)
        s.add("Mitigate", t.mitigation, .low)
        s.add("Reference", "https://attack.mitre.org/techniques/\(t.id.replacingOccurrences(of: ".", with: "/"))/")
        return ToolOutput(sections: [s])
    }
}
